// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only: a contract that pokes a decoy on behalf of whoever calls it,
/// to check that the decoy marks this contract and not the person calling.
contract Lure {
    address public immutable decoy;
    constructor(address decoy_) { decoy = decoy_; }
    function claimAirdrop() external {
        (bool ok,) = decoy.call(abi.encodeWithSignature("mint(address,uint256)", msg.sender, 1));
        require(ok, "decoy call failed");
    }
}

contracts/NeuroControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title NeuroControl: the governance knobs of Neuro (testnet)
/// @notice One place where the vote steers Neuro, separate from the coin:
///           - paused(): the Neuro stop button. NeuroJobs takes no new
///             requests or commits and runners stop taking jobs. It never
///             touches coin transfers, staking, bridges or withdrawals.
///             A guardian may pull it at once; only governance releases it.
///           - skills: a skill id (sha256 of Neuro's code, `zetaphy neuro
///             skill-id`) must be approved by a vote before jobs use it;
///             new jobs record activeSkill().
///           - the defender roster: runners governance allows to sit in the
///             4 defender seats of NeuroJobs (filled by its regrow()).
///           - release(runner): lets a quarantined runner work again.
///           - maxBodies: the cap on elastic bodies; maxRegrowPerHour: the
///             cap on refilling defender seats after an attack.
///           - communityFund: receives 5% of every job fee. The burned 5%
///             goes to BURN, an address nobody has a key for: it is locked
///             forever (still counted in the bank supply, never spendable).
///           - chains: the chain keys ("bsc", "eth", ...) NeuroJobs takes
///             requests for. A request for any other chain reverts, so fake
///             requests for chains no runner reads cannot inflate the bodies.
///             `zetaphy deploy` seeds it with the chains the runner supports.
///           - challenges: challengeBond (the least bond to challenge a
///             verdict; NeuroJobs asks max(2 x fee, this)), challengeWindow
///             (seconds after a quorum in which anyone may challenge; 0 =
///             NeuroJobs' jobTimeout) and defenderTimeout (a defender silent
///             longer than this loses its seat at the next regrow).
///         Governance is the chain's gov module (its EVM address, called
///         through a MsgEVMCall proposal: zetaphy-chain/gov.sh neuro ...) or
///         a SimpleMultisig.
///
///         Small read interface used by other contracts:
///           paused() returns (bool)
///           activeSkill() returns (bytes32)
///           defenderApproved(address) returns (bool)
///           releasedAt(address) returns (uint64)
///           maxBodies() / maxRegrowPerHour() returns (uint256)
///           communityFund() returns (address)
///           chainAllowed(bytes32) returns (bool)
///           challengeBond() / challengeWindow() / defenderTimeout() returns (uint256)
contract NeuroControl {
    /// Locked forever: no key exists for it.
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Bodies never go below the four defender seats.
    uint256 public constant MIN_BODIES = 4;
    uint256 public constant MAX_BODIES = 1000;
    uint256 public constant MAX_ROSTER = 32;
    uint256 public constant MAX_CHAINS_PER_CALL = 64;
    /// Bounds of the challenge window and the defender timeout (seconds).
    uint256 public constant MIN_WINDOW = 60;
    uint256 public constant MAX_WINDOW = 7 days;

    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;

    mapping(bytes32 => bool) public skillApproved;
    bytes32 public activeSkill;

    mapping(address => bool) public defenderApproved;
    address[] private _roster;

    /// When governance last released a runner from quarantine; a quarantine
    /// that started after this still holds.
    mapping(address => uint64) public releasedAt;

    uint256 public maxBodies;
    uint256 public maxRegrowPerHour;
    address public communityFund;

    /// Chain keys (bytes32 of e.g. "bsc") NeuroJobs accepts requests for.
    mapping(bytes32 => bool) public chainAllowed;

    /// Least challenge bond (NeuroJobs asks max(2 x job fee, this)).
    uint256 public challengeBond = 1 ether;
    /// Seconds after a quorum in which a verdict may be challenged; 0 = NeuroJobs' jobTimeout.
    uint256 public challengeWindow;
    /// A defender whose last heartbeat (or commit/reveal) is older than this loses its seat.
    uint256 public defenderTimeout = 6 hours;

    event GovernanceChanged(address governance);
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event SkillApproved(bytes32 indexed id);
    event SkillRevoked(bytes32 indexed id);
    event ActiveSkill(bytes32 indexed id);
    event DefenderApproved(address indexed runner);
    event DefenderRemoved(address indexed runner);
    event Released(address indexed runner);
    event MaxBodies(uint256 value);
    event MaxRegrowPerHour(uint256 value);
    event CommunityFund(address fund);
    event ChainApproved(bytes32 indexed chain);
    event ChainRemoved(bytes32 indexed chain);
    event ChallengeBond(uint256 value);
    event ChallengeWindow(uint256 value);
    event DefenderTimeout(uint256 value);

    error NotGovernance();
    error NotGuardian();
    error BadValue();
    error NotApproved();
    error SkillInUse();

    constructor(address governance_, address communityFund_, uint256 maxBodies_, uint256 maxRegrowPerHour_) {
        if (governance_ == address(0) || communityFund_ == address(0)) revert BadValue();
        if (maxBodies_ < MIN_BODIES || maxBodies_ > MAX_BODIES || maxRegrowPerHour_ == 0) revert BadValue();
        governance = governance_;
        communityFund = communityFund_;
        maxBodies = maxBodies_;
        maxRegrowPerHour = maxRegrowPerHour_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- stop button ----

    /// A guardian (or governance) stops Neuro at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Only a vote starts it again.
    function unpause() external onlyGovernance {
        paused = false;
        emit Unpaused();
    }

    function setGuardian(address who, bool allowed) external onlyGovernance {
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- skills ----

    function approveSkill(bytes32 id) external onlyGovernance {
        if (id == bytes32(0)) revert BadValue();
        skillApproved[id] = true;
        emit SkillApproved(id);
    }

    /// The active skill cannot be revoked: switch first (or pause).
    function revokeSkill(bytes32 id) external onlyGovernance {
        if (id == activeSkill) revert SkillInUse();
        skillApproved[id] = false;
        emit SkillRevoked(id);
    }

    function setActiveSkill(bytes32 id) external onlyGovernance {
        if (!skillApproved[id]) revert NotApproved();
        activeSkill = id;
        emit ActiveSkill(id);
    }

    // ---- defenders and quarantine ----

    function approveDefender(address runner) external onlyGovernance {
        if (runner == address(0) || defenderApproved[runner] || _roster.length == MAX_ROSTER) revert BadValue();
        defenderApproved[runner] = true;
        _roster.push(runner);
        emit DefenderApproved(runner);
    }

    /// Its seat (if any) is vacated by the next NeuroJobs.regrow().
    function removeDefender(address runner) external onlyGovernance {
        if (!defenderApproved[runner]) revert NotApproved();
        defenderApproved[runner] = false;
        for (uint256 i = 0; i < _roster.length; i++) {
            if (_roster[i] == runner) {
                _roster[i] = _roster[_roster.length - 1];
                _roster.pop();
                break;
            }
        }
        emit DefenderRemoved(runner);
    }

    function roster() external view returns (address[] memory) {
        return _roster;
    }

    function release(address runner) external onlyGovernance {
        releasedAt[runner] = uint64(block.timestamp);
        emit Released(runner);
    }

    // ---- sizes and money ----

    function setMaxBodies(uint256 n) external onlyGovernance {
        if (n < MIN_BODIES || n > MAX_BODIES) revert BadValue();
        maxBodies = n;
        emit MaxBodies(n);
    }

    function setMaxRegrowPerHour(uint256 n) external onlyGovernance {
        if (n == 0 || n > MAX_ROSTER) revert BadValue();
        maxRegrowPerHour = n;
        emit MaxRegrowPerHour(n);
    }

    function setCommunityFund(address fund) external onlyGovernance {
        if (fund == address(0)) revert BadValue();
        communityFund = fund;
        emit CommunityFund(fund);
    }

    // ---- challenges and defender liveness ----

    function setChallengeBond(uint256 amount) external onlyGovernance {
        if (amount == 0) revert BadValue();
        challengeBond = amount;
        emit ChallengeBond(amount);
    }

    /// 0 goes back to NeuroJobs' jobTimeout.
    function setChallengeWindow(uint256 secs) external onlyGovernance {
        if (secs != 0 && (secs < MIN_WINDOW || secs > MAX_WINDOW)) revert BadValue();
        challengeWindow = secs;
        emit ChallengeWindow(secs);
    }

    function setDefenderTimeout(uint256 secs) external onlyGovernance {
        if (secs < MIN_WINDOW || secs > MAX_WINDOW) revert BadValue();
        defenderTimeout = secs;
        emit DefenderTimeout(secs);
    }

    // ---- chains NeuroJobs takes requests for ----

    function approveChain(bytes32 chain) public onlyGovernance {
        if (chain == bytes32(0)) revert BadValue();
        chainAllowed[chain] = true;
        emit ChainApproved(chain);
    }

    /// Several at once (used at deploy to seed the runner's chain list).
    function approveChains(bytes32[] calldata chains) external onlyGovernance {
        if (chains.length == 0 || chains.length > MAX_CHAINS_PER_CALL) revert BadValue();
        for (uint256 i = 0; i < chains.length; i++) approveChain(chains[i]);
    }

    /// Jobs already requested for it keep running; new requests are refused.
    function removeChain(bytes32 chain) external onlyGovernance {
        if (!chainAllowed[chain]) revert NotApproved();
        chainAllowed[chain] = false;
        emit ChainRemoved(chain);
    }
}

contracts/NeuroIdentity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

/// NeuroJobs' runner record (the only part of NeuroJobs this registry reads).
interface IClaimRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title NeuroIdentity: one contract = one on-chain identity (ERC-8004 Identity Registry)
/// @notice An ERC-8004 ("Trustless Agents") Identity Registry: an ERC-721 whose
///         tokenId is the agentId and whose tokenURI (agentURI) resolves to the
///         agent registration file. On top of the plain ERC-8004 `register()`
///         calls, it gives every analysed contract, on any chain Neuro reads,
///         exactly one agent: "the Neuro of that contract".
///
///         Rules for a contract's identity (registerTarget / claim):
///         - Anyone may register a target. The identity is keyed by the target
///           (CAIP-10 style `namespace:reference:account`), so each target has
///           at most one, and the registry records who registered it.
///         - A new identity is held by this registry itself, so nobody (not the
///           registrant, not the admin) can edit, move or speak for it. Its
///           agentURI is built on-chain and points only at Neuro's report for
///           that target. A squatter therefore gains nothing: registering just
///           makes the Neuro report discoverable.
///         - The target's real owner can take control with proof. For a
///           contract on this chain: a call from the contract itself, or from
///           the address its `owner()` returns. Control follows the contract:
///           whoever can prove it now can claim again, even after a transfer.
///         - A target on another chain is claimed with `claimRemote`: its owner
///           (owner()/getOwner()/EIP-1967 admin on EVM, mint or upgrade
///           authority on Solana, ...) signs a consent off-chain, and at least
///           `claimQuorum` bonded Neuro runners (NeuroJobs: active, agreed > 0,
///           rejected <= agreed) attest with EIP-712 signatures that this key
///           is the target's owner on its chain right now. For an EVM owner the
///           consent itself is also checked here (ecrecover). Trust: the
///           runners' quorum is trusted to have read the owner correctly; for a
///           non-EVM owner (ed25519, ...) it is also trusted to have checked
///           the consent signature. Each claim uses the agent's `claimNonce`,
///           so attestations cannot be replayed.
///         - One spelling per target on chain: EVM/Move hex is lowercase, TON
///           friendly addresses (base64url, bounceable or not, testnet flag)
///           are converted to raw `0:hex` / `-1:hex` after their CRC16 check,
///           and a Bitcoin rune loses its spacers (• or .) and must be A-Z.
///         - A claimed identity behaves as a normal ERC-8004 agent (custom
///           agentURI, metadata, agentWallet, transfer). `neuroURI()` and
///           `getTarget()` still show what the identity is about, whatever its
///           owner writes in the agentURI.
///         - Nothing can be transferred to this registry. "Held by the
///           registry" therefore always means "never claimed, agentURI is
///           Neuro's own file": a claimed owner cannot set a custom URI and then
///           hand the token back to pass it off as an unclaimed identity.
contract NeuroIdentity {
    // ---------------------------------------------------------------- types

    struct MetadataEntry {
        string metadataKey;
        bytes metadataValue;
    }

    struct Target {
        string chain;        // Neuro chain key, e.g. "bsc"
        string account;      // canonical address / token id on that chain
        address registeredBy;
        uint64 registeredAt;
    }

    struct Chain {
        string caip2;        // e.g. "eip155:56"
        uint8 rule;          // RULE_*: how strictly the account is checked
        bool exists;
    }

    uint8 public constant RULE_TEXT = 0;      // [A-Za-z0-9._:-] and %XX (uppercase hex)
    uint8 public constant RULE_LOWER = 1;     // [a-z0-9._:-] only (bech32, NEAR, Starknet hex)
    uint8 public constant RULE_EVM = 2;       // 0x + 40 lowercase hex
    uint8 public constant RULE_MOVE = 3;      // 0x + 64 lowercase hex [::module::Name] (Sui, Aptos)
    uint8 public constant RULE_BASE58 = 4;    // 32-44 base58 characters (Solana)
    uint8 public constant RULE_TON = 5;       // stored raw: "0:" / "-1:" + 64 lowercase hex (friendly form converted)
    uint8 public constant RULE_RUNE = 6;      // stored A-Z only, 1-28 letters (spacers removed)

    string public constant name = "Neuro Agent Identity";
    string public constant symbol = "NEURO";
    string public constant REGISTRATION_TYPE = "https://eips.ethereum.org/EIPS/eip-8004#registration-v1";

    // ------------------------------------------------------------- storage

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    /// Last agentId handed out. Ids start at 1, so 0 means "none" (and "broadcast" in Neuro messages).
    uint256 public lastId;
    mapping(uint256 => string) private _uris;
    mapping(uint256 => mapping(string => bytes)) private _metadata;
    mapping(uint256 => Target) private _targets;
    /// keccak256(bytes(caip10)) => agentId
    mapping(bytes32 => uint256) public agentOfTarget;

    mapping(string => Chain) private _chains;
    string[] public chainKeys;
    bytes32 public immutable localCaip2Hash; // keccak256("eip155:<this chain id>")

    address public admin;
    string public webBase;   // Neuro web, e.g. "https://neuro.example/web/"
    string public imageURI;

    /// NeuroJobs (runner records) for claimRemote; zero = remote claims off. Fixed at deploy:
    /// whoever could change it could pick the runners and take any identity.
    IClaimRunners public immutable claimRunners;
    /// Runner attestations a remote claim needs.
    uint256 public immutable claimQuorum;
    /// Bumped by every claim (local or remote): attestations and consents name it, so each is used once.
    mapping(uint256 => uint256) public claimNonce;
    /// Spelling rules (NeuroTargets), created by the constructor.
    NeuroTargets public immutable targetFormat;

    // -------------------------------------------------------------- events

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    // ERC-4906
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);
    // ERC-8004
    event Registered(uint256 indexed agentId, string agentURI, address indexed owner);
    event MetadataSet(uint256 indexed agentId, string indexed indexedMetadataKey, string metadataKey, bytes metadataValue);
    event URIUpdated(uint256 indexed agentId, string newURI, address indexed updatedBy);
    // Neuro
    event TargetRegistered(uint256 indexed agentId, bytes32 indexed targetHash, string target, address indexed registeredBy);
    event Claimed(uint256 indexed agentId, address indexed by, address indexed previousOwner);
    event RemoteClaimed(uint256 indexed agentId, address indexed newOwner, bytes ownerKey, address[] runners);
    event ChainAdded(string key, string caip2, uint8 rule);
    event WebBaseSet(string webBase, string imageURI);
    event AdminSet(address admin);

    error NotAuthorized();
    error Nonexistent();
    error ReservedKey();
    error BadWallet();
    error Expired();
    error DeadlineTooFar();
    error InvalidSignature();
    error UnknownChain();
    error BadAccount();
    error BadValue();
    error ChainExists();
    error AlreadyRegistered(uint256 agentId);
    error NotTarget();
    error NotLocal();
    error NotTargetOwner();
    error AlreadyHolder();
    error UnsafeRecipient();
    error RegistryCustody();
    error RemoteClaimsOff();
    error NotRemote();
    error BadNonce();
    error NotRunner(address signer);
    error Quorum(uint256 have, uint256 need);

    bytes32 private constant AGENT_WALLET_SET_TYPEHASH =
        keccak256("AgentWalletSet(uint256 agentId,address newWallet,address owner,uint256 deadline)");
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant NAME_HASH = keccak256("ERC8004IdentityRegistry");
    bytes32 private constant VERSION_HASH = keccak256("1");
    uint256 private constant MAX_DEADLINE_DELAY = 5 minutes;
    /// A remote claim gathers several runners' signatures: allow up to a day.
    uint256 private constant MAX_CLAIM_DELAY = 1 days;
    bytes32 private constant CONSENT_TYPEHASH = keccak256(
        "RemoteClaimConsent(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant ATTEST_TYPEHASH = keccak256(
        "RemoteClaimAttestation(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant KEY_WALLET = keccak256("agentWallet");
    bytes32 private constant KEY_TARGET = keccak256("neuro.target");
    bytes32 private constant KEY_REGISTERED_BY = keccak256("neuro.registeredBy");

    constructor(string memory webBase_, string memory image_, string[] memory keys, string[] memory caip2s, uint8[] memory rules,
        address runners_, uint256 quorum_) {
        if (keys.length != caip2s.length || keys.length != rules.length) revert BadValue();
        if (runners_ != address(0) && quorum_ == 0) revert BadValue();
        claimRunners = IClaimRunners(runners_);
        targetFormat = new NeuroTargets();
        claimQuorum = quorum_;
        admin = msg.sender;
        localCaip2Hash = keccak256(bytes(string.concat("eip155:", _toString(block.chainid))));
        _setWeb(webBase_, image_);
        for (uint256 i; i < keys.length; i++) _addChain(keys[i], caip2s[i], rules[i]);
    }

    // ============================================================ ERC-165

    function supportsInterface(bytes4 id) external pure returns (bool) {
        return id == 0x01ffc9a7    // ERC-165
            || id == 0x80ac58cd    // ERC-721
            || id == 0x5b5e139f    // ERC-721 Metadata
            || id == 0x49064906;   // ERC-4906 (metadata update events)
    }

    // ============================================================ ERC-721

    function balanceOf(address owner) external view returns (uint256) {
        if (owner == address(0)) revert BadValue();
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address o) {
        o = _owners[tokenId];
        if (o == address(0)) revert Nonexistent();
    }

    function approve(address to, uint256 tokenId) external {
        address o = ownerOf(tokenId);
        if (msg.sender != o && !_operatorApprovals[o][msg.sender]) revert NotAuthorized();
        _tokenApprovals[tokenId] = to;
        emit Approval(o, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        ownerOf(tokenId);
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external {
        if (operator == address(0)) revert BadValue();
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        address o = ownerOf(tokenId);
        if (o != from) revert NotAuthorized();
        if (!_isAuthorized(o, msg.sender, tokenId)) revert NotAuthorized();
        if (to == address(0)) revert BadValue();
        // Custody is only for never-claimed identities (see the contract notes).
        if (to == address(this)) revert RegistryCustody();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    /// agentURI. A custom URI set by a claimed owner wins; otherwise a Neuro
    /// identity resolves to its on-chain registration file (`neuroURI`).
    function tokenURI(uint256 agentId) external view returns (string memory) {
        ownerOf(agentId);
        if (bytes(_uris[agentId]).length > 0) return _uris[agentId];
        if (bytes(_targets[agentId].chain).length > 0) return neuroURI(agentId);
        return "";
    }

    function _isAuthorized(address owner, address spender, uint256 tokenId) internal view returns (bool) {
        return spender != address(0)
            && (spender == owner || _operatorApprovals[owner][spender] || _tokenApprovals[tokenId] == spender);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        delete _tokenApprovals[tokenId];
        // ERC-8004: the verified agentWallet does not follow the token to a new owner.
        if (_metadata[tokenId]["agentWallet"].length > 0) {
            delete _metadata[tokenId]["agentWallet"];
            emit MetadataSet(tokenId, "agentWallet", "agentWallet", "");
        }
        unchecked {
            _balances[from] -= 1;
            _balances[to] += 1;
        }
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function _mint(address to, uint256 tokenId) internal {
        unchecked { _balances[to] += 1; }
        _owners[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
    }

    // ===================================================== ERC-8004 identity

    function register() external returns (uint256 agentId) {
        agentId = _registerPlain("");
    }

    function register(string calldata agentURI) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
    }

    function register(string calldata agentURI, MetadataEntry[] calldata metadata) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
        for (uint256 i; i < metadata.length; i++) {
            _requireFreeKey(metadata[i].metadataKey);
            _metadata[agentId][metadata[i].metadataKey] = metadata[i].metadataValue;
            emit MetadataSet(agentId, metadata[i].metadataKey, metadata[i].metadataKey, metadata[i].metadataValue);
        }
    }

    function _registerPlain(string memory agentURI) internal returns (uint256 agentId) {
        agentId = ++lastId;
        _metadata[agentId]["agentWallet"] = abi.encodePacked(msg.sender);
        _mint(msg.sender, agentId);
        if (bytes(agentURI).length > 0) _uris[agentId] = agentURI;
        emit Registered(agentId, agentURI, msg.sender);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(msg.sender));
        if (msg.sender.code.length > 0) {
            // _safeMint semantics: a contract registrant must accept ERC-721 tokens.
            try IERC721Receiver(msg.sender).onERC721Received(msg.sender, address(0), agentId, "") returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    function setAgentURI(uint256 agentId, string calldata newURI) external {
        _onlyAuthorized(agentId);
        _uris[agentId] = newURI;
        emit URIUpdated(agentId, newURI, msg.sender);
        emit MetadataUpdate(agentId);
    }

    function getMetadata(uint256 agentId, string memory metadataKey) external view returns (bytes memory) {
        bytes32 k = keccak256(bytes(metadataKey));
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length > 0) {
            if (k == KEY_TARGET) return bytes(_caip10(t));
            if (k == KEY_REGISTERED_BY) return abi.encodePacked(t.registeredBy);
        }
        return _metadata[agentId][metadataKey];
    }

    function setMetadata(uint256 agentId, string memory metadataKey, bytes memory metadataValue) external {
        _onlyAuthorized(agentId);
        _requireFreeKey(metadataKey);
        _metadata[agentId][metadataKey] = metadataValue;
        emit MetadataSet(agentId, metadataKey, metadataKey, metadataValue);
    }

    function getAgentWallet(uint256 agentId) external view returns (address) {
        bytes memory w = _metadata[agentId]["agentWallet"];
        if (w.length < 20) return address(0);
        return address(bytes20(w));
    }

    function setAgentWallet(uint256 agentId, address newWallet, uint256 deadline, bytes calldata signature) external {
        address owner = _onlyAuthorized(agentId);
        if (newWallet == address(0)) revert BadWallet();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_DEADLINE_DELAY) revert DeadlineTooFar();
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(AGENT_WALLET_SET_TYPEHASH, agentId, newWallet, owner, deadline))));
        if (_recover(digest, signature) != newWallet) {
            (bool ok, bytes memory res) = newWallet.staticcall(abi.encodeWithSelector(0x1626ba7e, digest, signature));
            if (!(ok && res.length >= 32 && bytes4(abi.decode(res, (bytes32))) == 0x1626ba7e)) revert InvalidSignature();
        }
        _metadata[agentId]["agentWallet"] = abi.encodePacked(newWallet);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(newWallet));
    }

    function unsetAgentWallet(uint256 agentId) external {
        _onlyAuthorized(agentId);
        delete _metadata[agentId]["agentWallet"];
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
    }

    /// As in the ERC-8004 reference implementation.
    function isAuthorizedOrOwner(address spender, uint256 agentId) external view returns (bool) {
        return _isAuthorized(ownerOf(agentId), spender, agentId);
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this)));
    }

    function getVersion() external pure returns (string memory) {
        return "neuro-1 (ERC-8004 identity v2.0.0 interface)";
    }

    function _onlyAuthorized(uint256 agentId) internal view returns (address owner) {
        owner = ownerOf(agentId);
        if (!_isAuthorized(owner, msg.sender, agentId)) revert NotAuthorized();
    }

    function _requireFreeKey(string memory key) internal pure {
        bytes32 k = keccak256(bytes(key));
        if (k == KEY_WALLET || k == KEY_TARGET || k == KEY_REGISTERED_BY) revert ReservedKey();
    }

    function _recover(bytes32 digest, bytes calldata sig) internal pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        if (v != 27 && v != 28) return address(0);
        return ecrecover(digest, v, r, s);
    }

    // ===================================================== Neuro: 1 contract = 1 identity

    /// Registers the Neuro of `account` on Neuro chain `chain` (e.g. "bsc").
    /// Anyone may call it; the identity stays held by this registry until the
    /// target's owner claims it. Reverts AlreadyRegistered(id) if it exists.
    function registerTarget(string calldata chain, string calldata typed) external returns (uint256 agentId) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        string memory account = _canonical(bytes(typed), c.rule);
        string memory caip10 = string.concat(c.caip2, ":", account);
        bytes32 h = keccak256(bytes(caip10));
        if (agentOfTarget[h] != 0) revert AlreadyRegistered(agentOfTarget[h]);
        agentId = ++lastId;
        agentOfTarget[h] = agentId;
        _targets[agentId] = Target(chain, account, msg.sender, uint64(block.timestamp));
        _mint(address(this), agentId);
        emit Registered(agentId, neuroURI(agentId), address(this));
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
        emit TargetRegistered(agentId, h, caip10, msg.sender);
    }

    /// Takes control of a ZETAPHY contract's identity: callable by the target
    /// contract itself or by the address its `owner()` returns right now.
    function claim(uint256 agentId) external {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        if (keccak256(bytes(_chains[t.chain].caip2)) != localCaip2Hash) revert NotLocal();
        address target = _parseAddress(bytes(t.account));
        bool ok = msg.sender == target;
        if (!ok && target.code.length > 0) {
            (bool s, bytes memory r) = target.staticcall(abi.encodeWithSignature("owner()"));
            ok = s && r.length >= 32 && abi.decode(r, (uint256)) == uint256(uint160(msg.sender));
        }
        if (!ok) revert NotTargetOwner();
        _takeOver(agentId, msg.sender);
    }

    /// Takes control of the identity of a target on ANOTHER chain, for
    /// `newOwner`. Anyone may submit it; the signatures decide.
    /// @param ownerKey   the target's owner/authority on its chain, as bytes
    ///                   (20-byte address on EVM, 32-byte ed25519 key on Solana, ...)
    /// @param ownerSig   for an EVM target: the owner's EIP-712 RemoteClaimConsent
    ///                   signature, checked here. Otherwise ignored (the runners checked it).
    /// @param attestations 65-byte EIP-712 RemoteClaimAttestation signatures by
    ///                   distinct runners, sorted by signer address (ascending).
    function claimRemote(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline,
        bytes calldata ownerSig, bytes[] calldata attestations) external {
        if (address(claimRunners) == address(0)) revert RemoteClaimsOff();
        (bytes memory fields, bool evmOwner) = _claimFields(agentId, newOwner, ownerKey, deadline);
        // An EVM owner proves its consent here, so the runners cannot move the
        // identity for a real owner who never asked.
        if (evmOwner && (ownerKey.length != 20 || _recover(_typed(CONSENT_TYPEHASH, fields), ownerSig) != address(bytes20(ownerKey)))) {
            revert InvalidSignature();
        }
        emit RemoteClaimed(agentId, newOwner, ownerKey, _runnerQuorum(_typed(ATTEST_TYPEHASH, fields), attestations));
        _takeOver(agentId, newOwner);
    }

    /// The signed fields of a remote claim (EIP-712: string and bytes members
    /// hashed, static words after the typehash), and whether the target is EVM.
    function _claimFields(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline)
        internal view returns (bytes memory, bool)
    {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        Chain storage c = _chains[t.chain];
        if (keccak256(bytes(c.caip2)) == localCaip2Hash) revert NotRemote();
        if (newOwner == address(0) || newOwner == address(this) || ownerKey.length == 0 || ownerKey.length > 64) revert BadValue();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_CLAIM_DELAY) revert DeadlineTooFar();
        return (abi.encode(agentId, newOwner, keccak256(bytes(_caip10(t))), keccak256(ownerKey), claimNonce[agentId], deadline), c.rule == RULE_EVM);
    }

    /// Signers of `digest`: distinct, ascending, each a runner in good standing, at least claimQuorum of them.
    function _runnerQuorum(bytes32 digest, bytes[] calldata sigs) internal view returns (address[] memory signers) {
        if (sigs.length < claimQuorum) revert Quorum(sigs.length, claimQuorum);
        signers = new address[](sigs.length);
        address last;
        for (uint256 i; i < sigs.length; i++) {
            address r = _recover(digest, sigs[i]);
            if (r <= last) revert InvalidSignature(); // zero, unsorted or repeated
            (, , bool active, uint32 agreed, uint32 rejected) = claimRunners.workers(r);
            if (!active || agreed == 0 || rejected > agreed) revert NotRunner(r);
            signers[i] = last = r;
        }
    }

    function _typed(bytes32 typehash, bytes memory fields) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), keccak256(abi.encodePacked(typehash, fields))));
    }

    function _takeOver(uint256 agentId, address to) internal {
        address prev = _owners[agentId];
        if (prev == to) revert AlreadyHolder();
        claimNonce[agentId]++;
        _transfer(prev, to, agentId);
        _metadata[agentId]["agentWallet"] = abi.encodePacked(to);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(to));
        emit Claimed(agentId, to, prev);
        emit MetadataUpdate(agentId);
    }

    /// agentId of a target, 0 if none (or if the chain is unknown). Any accepted
    /// spelling works (e.g. a TON friendly address, a rune with spacers).
    function agentIdOf(string calldata chain, string calldata account) external view returns (uint256) {
        Chain storage c = _chains[chain];
        if (!c.exists) return 0;
        (bool ok, string memory a) = targetFormat.canonical(bytes(account), c.rule);
        if (!ok) return 0;
        return agentOfTarget[keccak256(bytes(string.concat(c.caip2, ":", a)))];
    }

    /// The one spelling the registry stores for `account` on `chain`; reverts BadAccount.
    function canonicalAccount(string calldata chain, string calldata account) external view returns (string memory) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        return _canonical(bytes(account), c.rule);
    }

    function getTarget(uint256 agentId) external view returns (
        string memory chain, string memory caip10, string memory account, address registeredBy, uint64 registeredAt, bool claimed
    ) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return (t.chain, _caip10(t), t.account, t.registeredBy, t.registeredAt, _owners[agentId] != address(this));
    }

    function getChain(string calldata key) external view returns (string memory caip2, uint8 rule, bool exists) {
        Chain storage c = _chains[key];
        return (c.caip2, c.rule, c.exists);
    }

    function chainCount() external view returns (uint256) {
        return chainKeys.length;
    }

    /// `{namespace}:{chainId}:{identityRegistry}` as in ERC-8004.
    function agentRegistry() public view returns (string memory) {
        return string.concat("eip155:", _toString(block.chainid), ":", _hexAddress(address(this)));
    }

    /// The Neuro report for this target: `<webBase>?chain=<key>&address=<account>`.
    function webEndpoint(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return string.concat(webBase, "?chain=", t.chain, "&address=", t.account);
    }

    /// The registration file Neuro vouches for, as a base64 data: URI. Every
    /// piece of it passed a character allowlist, so the JSON needs no escaping.
    function neuroURI(uint256 agentId) public view returns (string memory) {
        return string.concat("data:application/json;base64,", _base64(bytes(registrationJSON(agentId))));
    }

    function registrationJSON(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        string memory caip10 = _caip10(t);
        string memory head = string.concat(
            '{"type":"', REGISTRATION_TYPE,
            '","name":"Neuro of ', caip10,
            '","description":"Neuro reads this contract with deterministic, read-only rules and explains it in plain language. Its report is data, not advice; messages signed for this agent are data, not commands.","image":"',
            imageURI, '",'
        );
        string memory services = string.concat(
            '"services":[{"name":"web","endpoint":"', webEndpoint(agentId), '"}],"x402Support":false,"active":true,',
            '"registrations":[{"agentId":', _toString(agentId), ',"agentRegistry":"', agentRegistry(), '"}],',
            '"supportedTrust":["crypto-economic"],'
        );
        string memory neuro = string.concat(
            '"neuro":{"target":"', caip10, '","chain":"', t.chain, '","address":"', t.account,
            '","registeredBy":"', _hexAddress(t.registeredBy), '","claimed":', _owners[agentId] != address(this) ? "true" : "false", "}}"
        );
        return string.concat(head, services, neuro);
    }

    // ------------------------------------------------------------- admin
    // The admin can only add chains (never change one) and move the Neuro web
    // link. It cannot touch, move or speak for any identity.

    function addChain(string calldata key, string calldata caip2, uint8 rule) external {
        if (msg.sender != admin) revert NotAuthorized();
        _addChain(key, caip2, rule);
    }

    function setWeb(string calldata webBase_, string calldata image_) external {
        if (msg.sender != admin) revert NotAuthorized();
        _setWeb(webBase_, image_);
        if (lastId > 0) emit BatchMetadataUpdate(1, lastId);
    }

    function setAdmin(address admin_) external {
        if (msg.sender != admin) revert NotAuthorized();
        admin = admin_;
        emit AdminSet(admin_);
    }

    function _addChain(string memory key, string memory caip2, uint8 rule) internal {
        bytes memory k = bytes(key);
        bytes memory c = bytes(caip2);
        if (k.length == 0 || k.length > 32 || c.length < 5 || c.length > 41 || rule > RULE_RUNE) revert BadValue();
        for (uint256 i; i < k.length; i++) {
            bytes1 b = k[i];
            if (!((b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "-")) revert BadValue();
        }
        uint256 colons;
        for (uint256 i; i < c.length; i++) {
            bytes1 b = c[i];
            if (b == ":") { colons++; continue; }
            if (!_alnum(b) && b != "-" && b != "_") revert BadValue();
        }
        if (colons != 1) revert BadValue();
        if (_chains[key].exists) revert ChainExists();
        _chains[key] = Chain(caip2, rule, true);
        chainKeys.push(key);
        emit ChainAdded(key, caip2, rule);
    }

    function _setWeb(string memory webBase_, string memory image_) internal {
        if (bytes(webBase_).length == 0) revert BadValue();
        _checkUrl(bytes(webBase_));
        _checkUrl(bytes(image_));
        webBase = webBase_;
        imageURI = image_;
        emit WebBaseSet(webBase_, image_);
    }

    // ------------------------------------------------------------- helpers

    /// Printable ASCII without quotes, backslash, angle brackets or spaces, at most 200 bytes.
    function _checkUrl(bytes memory u) internal pure {
        if (u.length > 200) revert BadValue();
        for (uint256 i; i < u.length; i++) {
            bytes1 b = u[i];
            if (b <= 0x20 || b >= 0x7f || b == '"' || b == "\\" || b == "<" || b == ">" || b == "`") revert BadValue();
        }
    }

    function _canonical(bytes memory a, uint8 rule) internal view returns (string memory) {
        (bool ok, string memory out) = targetFormat.canonical(a, rule);
        if (!ok) revert BadAccount();
        return out;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    /// Hex digit value, or 255. `upper` picks which letter case is accepted.
    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }

    function _parseAddress(bytes memory a) internal pure returns (address) {
        uint160 v;
        for (uint256 i = 2; i < 42; i++) v = v * 16 + _hexVal(a[i], false);
        return address(v);
    }

    function _caip10(Target storage t) internal view returns (string memory) {
        return string.concat(_chains[t.chain].caip2, ":", t.account);
    }

    function _toString(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 x = v; x != 0; x /= 10) len++;
        bytes memory out = new bytes(len);
        while (v != 0) { out[--len] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(out);
    }

    function _hexAddress(address a) internal pure returns (string memory) {
        bytes memory out = new bytes(42);
        out[0] = "0";
        out[1] = "x";
        bytes16 digits = "0123456789abcdef";
        uint160 v = uint160(a);
        for (uint256 i = 41; i > 1; i--) { out[i] = digits[v & 15]; v >>= 4; }
        return string(out);
    }

    function _base64(bytes memory data) internal pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 n = data.length;
        if (n == 0) return "";
        bytes memory out = new bytes(4 * ((n + 2) / 3));
        uint256 j;
        for (uint256 i; i < n; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < n ? uint8(data[i + 1]) : 0;
            uint256 c = i + 2 < n ? uint8(data[i + 2]) : 0;
            uint256 triple = (a << 16) | (b << 8) | c;
            out[j++] = table[(triple >> 18) & 63];
            out[j++] = table[(triple >> 12) & 63];
            out[j++] = i + 1 < n ? table[(triple >> 6) & 63] : bytes1("=");
            out[j++] = i + 2 < n ? table[triple & 63] : bytes1("=");
        }
        return string(out);
    }
}

/// @title NeuroTargets: the one spelling of a target account (NeuroIdentity's helper)
/// @notice Pure functions, split out so NeuroIdentity stays under the 24,576-byte
///         code limit. NeuroIdentity creates its own copy in its constructor.
contract NeuroTargets {
    uint8 internal constant RULE_TEXT = 0;
    uint8 internal constant RULE_LOWER = 1;
    uint8 internal constant RULE_EVM = 2;
    uint8 internal constant RULE_MOVE = 3;
    uint8 internal constant RULE_BASE58 = 4;
    uint8 internal constant RULE_TON = 5;
    uint8 internal constant RULE_RUNE = 6;

    /// (true, the one spelling) or (false, "") if `a` is not an account of that rule.
    function canonical(bytes memory a, uint8 rule) external pure returns (bool, string memory) {
        if (rule == RULE_TON) return _tonRaw(a);
        if (rule == RULE_RUNE) return _runeName(a);
        if (a.length > 128 || !_accountOk(a, rule)) return (false, "");
        return (true, string(a));
    }

    /// TON: raw `0:` / `-1:` + 64 hex (either case, stored lowercase), or the
    /// 48-character friendly form (base64 or base64url; bounceable 0x11 or
    /// non-bounceable 0x51, optionally | 0x80 testnet) with a valid CRC16.
    function _tonRaw(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(67);
        uint256 n;
        bytes memory hash;
        if (a.length == 48) {
            bytes memory d = new bytes(36);
            for (uint256 i; i < 48; i += 4) {
                uint256 w;
                for (uint256 j; j < 4; j++) {
                    uint8 v = _b64(a[i + j]);
                    if (v > 63) return (false, "");
                    w = (w << 6) | v;
                }
                uint256 k = (i / 4) * 3;
                d[k] = bytes1(uint8(w >> 16));
                d[k + 1] = bytes1(uint8(w >> 8));
                d[k + 2] = bytes1(uint8(w));
            }
            uint8 tag = uint8(d[0]) & 0x7f; // 0x80 = testnet only
            if (tag != 0x11 && tag != 0x51) return (false, "");
            uint256 crc;
            for (uint256 i; i < 34; i++) {
                crc ^= uint256(uint8(d[i])) << 8;
                for (uint256 b; b < 8; b++) crc = crc & 0x8000 != 0 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
            }
            if (crc != (uint256(uint8(d[34])) << 8 | uint8(d[35]))) return (false, "");
            if (d[1] == 0x00) { out[0] = "0"; n = 1; }
            else if (d[1] == 0xff) { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) hash[i] = d[i + 2];
        } else {
            if (a.length == 66 && a[0] == "0" && a[1] == ":") { out[0] = "0"; n = 1; }
            else if (a.length == 67 && a[0] == "-" && a[1] == "1" && a[2] == ":") { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) {
                uint8 hi = _hexAny(a[n + 1 + 2 * i]);
                uint8 lo = _hexAny(a[n + 2 + 2 * i]);
                if (hi > 15 || lo > 15) return (false, "");
                hash[i] = bytes1(hi * 16 + lo);
            }
        }
        out[n] = ":";
        bytes16 digits = "0123456789abcdef";
        for (uint256 i; i < 32; i++) {
            out[n + 1 + 2 * i] = digits[uint8(hash[i]) >> 4];
            out[n + 2 + 2 * i] = digits[uint8(hash[i]) & 15];
        }
        assembly { mstore(out, add(n, 65)) }
        return (true, string(out));
    }

    /// Rune name: spacers (U+2022 "•" as UTF-8 or %E2%80%A2, and ".") are
    /// dropped; what is left must be 1-28 letters A-Z.
    function _runeName(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(a.length);
        uint256 n;
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (b >= "A" && b <= "Z") { out[n++] = b; continue; }
            if (b == ".") continue;
            if (b == 0xe2 && i + 2 < a.length && a[i + 1] == 0x80 && a[i + 2] == 0xa2) { i += 2; continue; }
            if (b == "%" && i + 8 < a.length && keccak256(abi.encodePacked(a[i + 1], a[i + 2], a[i + 3], a[i + 4], a[i + 5], a[i + 6], a[i + 7], a[i + 8]))
                == keccak256("E2%80%A2")) { i += 8; continue; }
            return (false, "");
        }
        if (n == 0 || n > 28) return (false, "");
        assembly { mstore(out, n) }
        return (true, string(out));
    }

    function _b64(bytes1 c) internal pure returns (uint8) {
        if (c >= "A" && c <= "Z") return uint8(c) - 65;
        if (c >= "a" && c <= "z") return uint8(c) - 71;
        if (c >= "0" && c <= "9") return uint8(c) + 4;
        if (c == "-" || c == "+") return 62;
        if (c == "_" || c == "/") return 63;
        return 255;
    }

    function _hexAny(bytes1 b) internal pure returns (uint8) {
        uint8 v = _hexVal(b, false);
        return v < 16 ? v : _hexVal(b, true);
    }

    /// The account checks of the other rules: the input must already be the one spelling.
    function _accountOk(bytes memory a, uint8 rule) internal pure returns (bool) {
        if (a.length == 0 || a.length > 128) return false;
        if (rule == RULE_EVM) {
            if (a.length != 42 || a[0] != "0" || a[1] != "x") return false;
            for (uint256 i = 2; i < 42; i++) if (_hexVal(a[i], false) > 15) return false;
            return true;
        }
        if (rule == RULE_MOVE) return _moveOk(a);
        if (rule == RULE_BASE58) {
            if (a.length < 32 || a.length > 44) return false;
            for (uint256 i; i < a.length; i++) {
                bytes1 b = a[i];
                if (!_alnum(b) || b == "0" || b == "O" || b == "I" || b == "l") return false;
            }
            return true;
        }
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (_safeLower(b)) continue;
            if (rule == RULE_TEXT) {
                if (b >= "A" && b <= "Z") continue;
                // %XX with uppercase hex, the one canonical spelling of an escaped byte;
                // a byte that needs no escape (e.g. %41 for "A") is a second spelling, so refused
                if (b == "%" && i + 2 < a.length && _hexVal(a[i + 1], true) < 16 && _hexVal(a[i + 2], true) < 16) {
                    bytes1 d = bytes1(_hexVal(a[i + 1], true) * 16 + _hexVal(a[i + 2], true));
                    if (_safeLower(d) || (d >= "A" && d <= "Z")) return false;
                    i += 2;
                    continue;
                }
            }
            return false;
        }
        return true;
    }

    /// Move: "0x" + 64 lowercase hex (the padded address), optionally followed
    /// by "::module::Name" with identifiers [A-Za-z_][A-Za-z0-9_]*.
    function _moveOk(bytes memory a) internal pure returns (bool) {
        if (a.length < 66 || a[0] != "0" || a[1] != "x") return false;
        for (uint256 j = 2; j < 66; j++) if (_hexVal(a[j], false) > 15) return false;
        if (a.length == 66) return true;
        uint256 i = 66;
        for (uint256 part; part < 2; part++) {
            if (i + 2 >= a.length || a[i] != ":" || a[i + 1] != ":") return false;
            i += 2;
            bytes1 f = a[i];
            if (!((f >= "a" && f <= "z") || (f >= "A" && f <= "Z") || f == "_")) return false;
            while (i < a.length && a[i] != ":") {
                if (!_alnum(a[i]) && a[i] != "_") return false;
                i++;
            }
        }
        return i == a.length;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }
}

contracts/NeuroJobs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// What NeuroJobs reads from NeuroControl (contracts/NeuroControl.sol).
interface INeuroKnobs {
    function paused() external view returns (bool);
    function activeSkill() external view returns (bytes32);
    function defenderApproved(address) external view returns (bool);
    function roster() external view returns (address[] memory);
    function releasedAt(address) external view returns (uint64);
    function maxBodies() external view returns (uint256);
    function maxRegrowPerHour() external view returns (uint256);
    function communityFund() external view returns (address);
    function chainAllowed(bytes32) external view returns (bool);
    function challengeBond() external view returns (uint256);
    function challengeWindow() external view returns (uint256);
    function defenderTimeout() external view returns (uint256);
}

/// @title NeuroJobs: the Neuro ZETAPHY job market (testnet, stage 1-2)
/// @notice Someone asks for a contract to be checked and pays a fee in ZETAPHY.
///         Up to three bonded node runners each compute Neuro's verdict on their
///         own machine. The verdict stands once two of them agree, and those two
///         share the fee plus a reward from the pool.
///
///         Commit-reveal stops a runner from copying another's answer: runners
///         first post keccak256(verdict, runner, salt), and reveal only after
///         all seats are taken or the commit window closes.
///
///         Payouts are credited, then pulled with withdraw() (no ETH is pushed
///         to arbitrary addresses inside the job logic).
///
///         Seats are not first-come: per job, a lottery weighted by bond
///         decides who may commit (eligible()). Only runners that registered
///         before the job count, and splitting one bond over many addresses
///         does not raise the odds. Pool rewards are capped at a quarter of
///         the fee per winner and per day, so requesting jobs for oneself
///         does not pay.
///
///         Unpredictable lottery: a request records nothing random. The
///         lottery is drawn later, once, by the first commit or by draw(id)
///         (anyone), in a block after the request block:
///           rand = keccak256(seed, block.prevrandao, round)
///         seed comes from the request (requester, chain, target, time, the
///         requester's own counter). On zetaphyd with the PQ certificate
///         patch, PREVRANDAO is derived from the previous block's ML-DSA
///         vote certificate, so the requester cannot know who will be
///         eligible when it sends the request. eligible() is false for
///         everyone until the draw. Where PREVRANDAO is constant (older
///         zetaphyd binaries, the unit-test EVM) the draw still works, and
///         the lottery is as predictable as the request data alone (the
///         behaviour before this change). Runners call draw() as soon as
///         they see a request, so a requester cannot wait for a block it
///         likes unless nobody else is watching.
///
///         Fee: 90% to the runners whose verdict stood, 5% burned (sent to
///         0x…dEaD, locked forever), 5% to the community fund (credited; it
///         withdraws like a runner). Rounding dust goes to the community
///         fund, so fee = runners + burned + community to the wei. A failed
///         or expired job refunds the fee minus FAIL_BURN_BPS (5%), which is
///         burned: whoever makes fake or unanswerable requests pays for them.
///
///         Bodies (runners eligible per job) are elastic:
///           bodies = DEFENDERS + ceil(requests per minute / CAPACITY_PER_BODY)
///         capped by NeuroControl.maxBodies(). Requests per minute is the
///         busiest recent minute, fading linearly to zero over DECAY_MINUTES:
///         N requests in a minute count as N*(30-age)/30 after `age` whole
///         minutes, so with no use the extra bodies shrink step by step and
///         are gone after 30 minutes. Only requests that pass every check
///         count, and with a NeuroControl only chains on its allowlist
///         (chainAllowed) are accepted, so requests no runner can answer
///         cannot inflate the bodies; even refunded ones lose 5%.
///
///         Immune system: 4 defender seats, filled by regrow() (anyone may
///         call it) from NeuroControl's voted roster, at most
///         maxRegrowPerHour refills per hour. Defenders are always eligible,
///         but at most one defender sits on a round: a second may commit
///         only after the first third of the commit window, and only while
///         no drawn runner has committed (so two defenders cannot decide a
///         verdict together while the lottery has runners to offer).
///         Runners call heartbeat() (a commit or reveal counts too); a
///         defender silent for longer than NeuroControl.defenderTimeout()
///         stops being a defender at once, the next regrow() vacates its
///         seat, and regrow() seats it again only after a fresh heartbeat.
///
///         Strikes: a rejected verdict, and a seat that committed but never
///         revealed, each cost PENALTY_BPS of the bond and a strike.
///         QUARANTINE_AFTER strikes within a runner's last STRIKE_WINDOW
///         judged seats put it in quarantine (lying every other job does not
///         reset it). A quarantined runner stops being active at once: it
///         drops out of activeWorkers and totalActiveBond, so other
///         contracts reading workers() no longer count it, and its bond
///         starts unbonding (withdrawBond after unbondDelay, minus
///         penalties). Seats it already holds can still be revealed. Its
///         defender seat is vacated, and register() refuses the address
///         until governance releases it (NeuroControl.release).
///
///         Unrevealed seats: once a quorum forms, a seat that has not
///         revealed yet gets a grace of commitWindow seconds to reveal (it
///         is judged like the others, but the fee is already shared). After
///         the grace anyone may call settle(id): every seat still unrevealed
///         gets the penalty and a strike. A job that times out (expire())
///         does the same at once.
///
///         Challenge round: verdicts are deterministic, so anyone can re-run
///         Neuro and prove a bad pair wrong. Until challengeUntil (the
///         finalize time plus NeuroControl.challengeWindow(), or jobTimeout
///         when that is 0) anyone may call challenge(id) with a bond of at
///         least max(2 x fee, NeuroControl.challengeBond()). That opens round
///         2: 3 fresh seats, drawn with the same lottery (its own draw, in a
///         later block), never a round-1 seat or the challenger; commit-
///         reveal and 2 of 3 as in round 1. One challenge per job.
///           - Round 2 overturns round 1: each round-1 runner that revealed
///             the overturned verdict loses CHALLENGE_SLASH_BPS (50%) of its
///             bond and gets a strike. The challenger gets its bond back plus
///             half of the slashed sum; the other half is shared by round-2
///             winners and round-1 seats that had revealed the new verdict.
///             The job's result becomes round 2's.
///           - Round 2 confirms round 1: the challenger's bond is shared,
///             half by the round-2 winners, half by the round-1 winners.
///           - No quorum in round 2 (all revealed and none agree, or
///             jobTimeout passed: challengeExpire): the bond goes back, the
///             verdict stands but is marked Disputed.
///         Round 2 has the same reveal grace and settle() as round 1. A
///         round-1 runner's bond cannot be withdrawn until challengeUntil +
///         jobTimeout of every job it sat on, so a pair cannot leave before
///         a challenge is resolved. The fee shares of round 1 are paid at
///         once and are not taken back: the 50% slash is the deterrent.
///         Rounding dust always goes to the community fund (to the wei).
///         assurance(id) shows how many runners agreed with the final
///         verdict (2, 3, or 4+ after a confirmed challenge) and the
///         challenge state.
///
///         NeuroControl's paused() stops new requests, challenges and commits
///         only; reveals, expiry, refunds and withdrawals keep working. Each
///         job records the voted skill (activeSkill) it was requested under.
///
///         Without a NeuroControl (setControl never called) nothing is
///         paused, jobs carry skill 0, any chain key is accepted, there are
///         no defenders, bodies are uncapped, challenges need 2 x fee and
///         last jobTimeout, and the community share goes to the reward pool.
///         `zetaphy deploy` calls setControl right after deploying, so only
///         jobs slipped in during those blocks have skill 0: runners that
///         follow governance skip them, so they expire and refund (minus
///         the 5% slice).
contract NeuroJobs {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    /// Share of the bond a runner loses for a verdict the quorum rejected,
    /// or for committing and then never revealing (basis points).
    uint16 public constant PENALTY_BPS = 1000;
    /// Fee split (basis points of the fee); the runners get the rest (90%).
    uint16 public constant BURN_BPS = 500;
    uint16 public constant COMMUNITY_BPS = 500;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Defender seats; also the fewest bodies there ever are.
    uint8 public constant DEFENDERS = 4;
    /// Requests per minute one body is expected to handle.
    uint256 public constant CAPACITY_PER_BODY = 6;
    /// Minutes for the extra bodies to fade out after the last busy minute.
    uint256 public constant DECAY_MINUTES = 30;
    /// Strikes within the last STRIKE_WINDOW judged seats that put a runner in quarantine (K).
    uint8 public constant QUARANTINE_AFTER = 2;
    uint8 public constant STRIKE_WINDOW = 5;
    /// Share of a failed or expired job's fee that is burned instead of refunded.
    uint16 public constant FAIL_BURN_BPS = 500;
    /// Longest target: a Move coin type (66-char address + two 128-char names + separators).
    uint256 public constant MAX_TARGET = 330;
    /// Share of its bond a round-1 runner loses when a challenge overturns its verdict.
    uint16 public constant CHALLENGE_SLASH_BPS = 5000;
    /// The challenge bond is at least this many times the job fee.
    uint256 public constant CHALLENGE_FEE_MULTIPLE = 2;

    uint256 public immutable workerBond;
    uint256 public immutable jobReward;
    uint256 public immutable minFee;
    uint64 public immutable commitWindow;
    uint64 public immutable jobTimeout;
    uint64 public immutable unbondDelay;
    uint256 public immutable dailyRewardCap;
    /// May call setControl() once.
    address public immutable deployer;

    enum Status { None, Open, Done, Failed }
    enum ChallengeState { None, Open, Confirmed, Overturned, Disputed }

    struct Worker {
        uint128 bond;
        uint64 unbondAt; // 0 while active
        bool active;
        uint32 agreed;
        uint32 rejected;
        uint64 since;    // when it last became active; only later jobs count
        uint8 recent;    // last STRIKE_WINDOW judged seats, newest in bit 0; 1 = strike
        uint64 quarantinedAt; // 0 = never; see quarantined()
        uint64 lastSeen;  // last register, heartbeat, commit or reveal
        uint64 heldUntil; // bond stays until every job it sat on is past its challenge
    }

    /// One round of 3 seats (round 1 = the job, round 2 = a challenge).
    struct Round {
        uint8 commits;
        uint8 reveals;
        uint8 defenders;   // seats taken as a defender
        uint64 start;      // the commit window starts here
        uint64 startBlock; // the draw must come in a later block
        bytes32 rand;      // the lottery; 0 until drawn
        address[3] seat;
        bytes32[3] commitOf;
        bytes32[3] verdictOf;
        bool[3] revealed;
    }

    struct Job {
        address requester;
        Status status;
        uint8 agreedBy;  // distinct runners that revealed the final verdict
        uint16 bodies;   // bodies when requested
        uint16 drawn;    // of which drawn by lottery (bodies minus seated defenders)
        uint64 settleAt; // quorum reached with seats unrevealed: grace ends here (0 = nothing pending)
        uint64 challengeUntil; // set when the quorum forms
        bytes32 chain;
        uint256 fee;
        bytes32 result;
        bytes32 seed;
        bytes32 skill;   // NeuroControl.activeSkill() at request time
        string target;
        Round r;
    }

    struct Challenge {
        address challenger;
        ChallengeState state;
        uint64 settleAt;
        uint256 bond;
        bytes32 result;
        Round r;
    }

    uint256 public rewardPool;
    uint256 public activeWorkers;
    uint256 public totalActiveBond;
    uint64 public rewardDay;
    uint256 public rewardedToday;
    mapping(address => uint256) public requestCount;
    mapping(address => Worker) public workers;
    mapping(address => uint256) public credit;
    Job[] internal jobs;
    mapping(uint256 => Challenge) internal challenges;
    /// Ids of challenged jobs, in order (runners scan it for round-2 seats).
    uint256[] public challenged;

    INeuroKnobs public control;
    address[4] public defender;
    uint64 public regrowHour;
    uint256 public regrownThisHour;
    uint256 public totalBurned;
    // Load meter: requests in the latest minute that had any, and the
    // busiest earlier minute still fading (see bodies()).
    uint64 public loadMinute;
    uint64 public loadCount;
    uint64 public peakMinute;
    uint64 public peakCount;

    event Funded(address indexed from, uint256 amount);
    event Registered(address indexed worker, uint256 bond);
    event UnbondRequested(address indexed worker, uint64 at);
    event JobRequested(uint256 indexed id, bytes32 indexed chain, string target, uint256 fee);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event Finalized(uint256 indexed id, bytes32 verdict);
    event JobFailed(uint256 indexed id);
    event Penalized(address indexed worker, uint256 amount);
    event ControlSet(address control);
    event JobSized(uint256 indexed id, bytes32 indexed skill, uint256 bodies, uint256 drawn);
    event FeeSplit(uint256 indexed id, uint256 runners, uint256 burned, uint256 community);
    event Quarantined(address indexed worker);
    event DefenderSeated(address indexed worker, uint256 seat);
    event DefenderVacated(address indexed worker, uint256 seat);
    event Missed(uint256 indexed id, address indexed worker);
    event Settled(uint256 indexed id);
    event Drawn(uint256 indexed id, uint8 round, bytes32 rand);
    event Challenged(uint256 indexed id, address indexed challenger, uint256 bond);
    event ChallengeCommitted(uint256 indexed id, address indexed worker);
    event ChallengeRevealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event ChallengeResolved(uint256 indexed id, ChallengeState state, bytes32 verdict);

    error BadValue();
    error BadJob();
    error NotWorker();
    error Closed();
    error AlreadyIn();
    error NoSeat();
    error TooEarly();
    error BadReveal();
    error Nothing();
    error NotChosen();
    error Paused();
    error NoSkill();
    error NoControl();
    error NotDeployer();
    error UnknownChain();
    error InQuarantine();

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_) {
        if (bond_ == 0 || commitWindow_ == 0 || timeout_ <= commitWindow_ || unbondDelay_ < timeout_) revert BadValue();
        workerBond = bond_;
        jobReward = reward_;
        minFee = minFee_;
        commitWindow = commitWindow_;
        jobTimeout = timeout_;
        unbondDelay = unbondDelay_;
        dailyRewardCap = dailyRewardCap_;
        deployer = msg.sender;
    }

    /// Wires in NeuroControl. Once, by the deployer. Jobs requested before
    /// it keep skill 0 (see above), so a request slipped in first cannot
    /// block it.
    function setControl(INeuroKnobs control_) external {
        if (msg.sender != deployer) revert NotDeployer();
        if (address(control) != address(0) || address(control_) == address(0)) revert BadValue();
        control = control_;
        emit ControlSet(address(control_));
    }

    // ---- pool and runners ----

    function fund() external payable {
        if (msg.value == 0) revert BadValue();
        rewardPool += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    function register() external payable {
        Worker storage w = workers[msg.sender];
        if (w.active) revert AlreadyIn();
        if (w.unbondAt != 0) revert TooEarly(); // finish leaving first
        if (quarantined(msg.sender)) revert InQuarantine();
        uint256 bond = uint256(w.bond) + msg.value;
        if (bond < workerBond) revert BadValue();
        w.bond = uint128(bond);
        w.active = true;
        w.since = uint64(block.timestamp);
        w.lastSeen = uint64(block.timestamp);
        activeWorkers += 1;
        totalActiveBond += bond;
        emit Registered(msg.sender, bond);
    }

    /// "Still here": keeps a defender seat (see defenderTimeout). Costs only gas.
    function heartbeat() external {
        Worker storage w = workers[msg.sender];
        if (!w.active) revert NotWorker();
        w.lastSeen = uint64(block.timestamp);
    }

    /// Leaving takes unbondDelay, so a runner cannot escape a penalty on a job
    /// it is still part of.
    function requestUnbond() external {
        Worker storage w = workers[msg.sender];
        if (!w.active) revert NotWorker();
        w.active = false;
        w.unbondAt = uint64(block.timestamp) + unbondDelay;
        activeWorkers -= 1;
        totalActiveBond -= w.bond;
        emit UnbondRequested(msg.sender, w.unbondAt);
    }

    /// Also waits for heldUntil: the challenge window (and a challenge round)
    /// of every job the runner sat on.
    function withdrawBond() external {
        Worker storage w = workers[msg.sender];
        if (w.active || w.unbondAt == 0 || block.timestamp < w.unbondAt || block.timestamp < w.heldUntil) revert TooEarly();
        uint256 amount = w.bond;
        w.bond = 0;
        w.unbondAt = 0;
        credit[msg.sender] += amount;
    }

    function withdraw() external {
        uint256 amount = credit[msg.sender];
        if (amount == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    // ---- jobs ----

    /// @param chain   chain key as bytes32, e.g. "bsc"
    /// @param target  address on that chain (EVM hex, Solana base58, a Move coin
    ///                type such as 0x…::module::NAME, or a TON address), at most MAX_TARGET bytes
    function request(bytes32 chain, string calldata target) external payable returns (uint256 id) {
        return _request(msg.sender, chain, target);
    }

    /// Same as request(), but a refund goes to `refundTo`. Used by StableGateway,
    /// which pays the fee for a user who paid it in a stablecoin.
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256 id) {
        if (refundTo == address(0)) revert BadValue();
        return _request(refundTo, chain, target);
    }

    function _request(address requester, bytes32 chain, string calldata target) private returns (uint256 id) {
        if (msg.value < minFee || chain == bytes32(0) || bytes(target).length == 0 || bytes(target).length > MAX_TARGET) revert BadValue();
        bytes32 skill;
        if (address(control) != address(0)) {
            if (control.paused()) revert Paused();
            skill = control.activeSkill();
            if (skill == bytes32(0)) revert NoSkill();
            if (!control.chainAllowed(chain)) revert UnknownChain();
        }
        _countRequest();
        id = jobs.length;
        Job storage j = jobs.push();
        j.requester = requester;
        j.r.start = uint64(block.timestamp);
        j.r.startBlock = uint64(block.number);
        // Not the job id: jobs slipped in first must not move the seed.
        // Nothing random yet: the lottery is drawn in a later block (draw()).
        j.seed = keccak256(abi.encode(requester, chain, target, block.timestamp, requestCount[requester]++));
        j.status = Status.Open;
        j.chain = chain;
        j.target = target;
        j.fee = msg.value;
        j.skill = skill;
        uint256 b = bodies();
        uint256 seated = _seatedDefenders();
        j.bodies = uint16(b);
        j.drawn = uint16(b > seated ? b - seated : 0);
        emit JobRequested(id, chain, target, msg.value);
        emit JobSized(id, skill, b, j.drawn);
    }

    /// Draws the lottery of the round now taking seats (round 1 while the
    /// job is open, else an open challenge's round 2). Anyone may; once per
    /// round; only in a block after the request (or challenge) block. The
    /// first commit draws too.
    function draw(uint256 id) external {
        Job storage j = _job(id);
        Challenge storage ch = challenges[id];
        if (j.status == Status.Open && j.r.rand == 0) _draw(id, j, j.r, 1);
        else if (ch.state == ChallengeState.Open && ch.r.rand == 0) _draw(id, j, ch.r, 2);
        else revert Nothing();
    }

    /// @param commitment keccak256(abi.encode(verdict, msg.sender, salt))
    function commit(uint256 id, bytes32 commitment) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        _take(id, j, j.r, 1, commitment);
        emit Committed(id, msg.sender);
    }

    /// Also open after a quorum, until settleAt, for a seat that had not
    /// revealed yet: it is judged against the result (no fee share).
    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        Round storage r = j.r;
        if (j.status == Status.Open) {
            if (r.commits < SEATS && block.timestamp < r.start + commitWindow) revert TooEarly();
        } else if (j.settleAt == 0 || block.timestamp >= j.settleAt) {
            revert Closed();
        }
        uint8 same = _reveal(r, verdict, salt);
        emit Revealed(id, msg.sender, verdict);

        if (j.status != Status.Open) {
            // Late reveal inside the grace after a quorum.
            bool ok = verdict == j.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { j.settleAt = 0; emit Settled(id); }
            return;
        }

        // Quorum: this verdict matches QUORUM-1 earlier reveals.
        if (same >= QUORUM) _finalize(id, j, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) {
            // Everyone who committed has revealed and no two agree.
            _fail(id, j, false);
        }
    }

    /// Anyone can close a job that ran out of time without a quorum.
    function expire(uint256 id) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        if (block.timestamp < j.r.start + jobTimeout) revert TooEarly();
        _fail(id, j, true);
    }

    /// Anyone, once the reveal grace after a quorum is over (in round 1 or
    /// a challenge's round 2): every seat that committed and still has not
    /// revealed gets the penalty and a strike.
    function settle(uint256 id) external {
        Job storage j = _job(id);
        Challenge storage ch = challenges[id];
        bool any;
        if (_settleRound(id, j.r, j.settleAt)) { j.settleAt = 0; any = true; }
        if (_settleRound(id, ch.r, ch.settleAt)) { ch.settleAt = 0; any = true; }
        if (!any) {
            if (j.settleAt != 0 || ch.settleAt != 0) revert TooEarly();
            revert Nothing();
        }
        emit Settled(id);
    }

    // ---- challenge round ----

    /// The least bond challenge(id) takes: max(2 x fee, NeuroControl.challengeBond()).
    function challengeBondOf(uint256 id) public view returns (uint256 b) {
        b = _job(id).fee * CHALLENGE_FEE_MULTIPLE;
        if (address(control) != address(0)) {
            uint256 floor_ = control.challengeBond();
            if (floor_ > b) b = floor_;
        }
    }

    /// Anyone who re-ran Neuro and got another verdict: opens round 2 (see
    /// above). The whole msg.value is the bond. Once per job, before
    /// challengeUntil.
    function challenge(uint256 id) external payable {
        Job storage j = _job(id);
        Challenge storage ch = challenges[id];
        if (j.status != Status.Done || block.timestamp >= j.challengeUntil) revert Closed();
        if (ch.state != ChallengeState.None) revert AlreadyIn();
        if (_paused()) revert Paused();
        if (msg.value < challengeBondOf(id)) revert BadValue();
        ch.challenger = msg.sender;
        ch.state = ChallengeState.Open;
        ch.bond = msg.value;
        ch.r.start = uint64(block.timestamp);
        ch.r.startBlock = uint64(block.number);
        challenged.push(id);
        emit Challenged(id, msg.sender, msg.value);
    }

    function challengeCommit(uint256 id, bytes32 commitment) external {
        Job storage j = _job(id);
        Challenge storage ch = challenges[id];
        if (ch.state != ChallengeState.Open) revert Closed();
        _take(id, j, ch.r, 2, commitment);
        emit ChallengeCommitted(id, msg.sender);
    }

    /// Like reveal(), for a round-2 seat (with the same grace after its quorum).
    function challengeReveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        Challenge storage ch = challenges[id];
        Round storage r = ch.r;
        if (ch.state == ChallengeState.Open) {
            if (r.commits < SEATS && block.timestamp < r.start + commitWindow) revert TooEarly();
        } else if (ch.settleAt == 0 || block.timestamp >= ch.settleAt) {
            revert Closed();
        }
        uint8 same = _reveal(r, verdict, salt);
        emit ChallengeRevealed(id, msg.sender, verdict);

        if (ch.state != ChallengeState.Open) {
            bool ok = verdict == ch.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { ch.settleAt = 0; emit Settled(id); }
            return;
        }
        if (same >= QUORUM) _resolve(id, j, ch, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) _dispute(id, ch, false);
    }

    /// Anyone, jobTimeout after the challenge, if round 2 found no quorum:
    /// the challenger's bond goes back, the verdict stands (Disputed), and
    /// round-2 seats that never revealed are penalized.
    function challengeExpire(uint256 id) external {
        _job(id);
        Challenge storage ch = challenges[id];
        if (ch.state != ChallengeState.Open) revert Closed();
        if (block.timestamp < ch.r.start + jobTimeout) revert TooEarly();
        _dispute(id, ch, true);
    }

    // ---- views ----

    function jobCount() external view returns (uint256) {
        return jobs.length;
    }

    function challengeCount() external view returns (uint256) {
        return challenged.length;
    }

    function getJob(uint256 id) external view returns (
        address requester, uint64 created, Status status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat
    ) {
        Job storage j = _job(id);
        return (j.requester, j.r.start, j.status, j.chain, j.target, j.fee, j.result, j.r.commits, j.r.reveals, j.r.seat);
    }

    /// May `w` take a round-1 seat on job `id` right now? False until the
    /// lottery is drawn (draw()). A seated defender may if no defender sits
    /// on the job yet (or, after the first third of the commit window, if
    /// only defenders have committed). Everyone else goes by a bond-weighted
    /// lottery: about `drawn` runners (the job's bodies minus seated
    /// defenders) qualify at first, twice as many (at least 2 x SEATS)
    /// after the first third of the commit window, and every runner in the
    /// last third, so seats always fill while runners are online, whatever
    /// the draw. Only runners active since before the job, never
    /// quarantined ones.
    function eligible(uint256 id, address w) public view returns (bool ok) {
        if (id >= jobs.length) return false;
        (ok,) = _eligible(id, jobs[id].r, w, 1);
    }

    /// Same for round 2 of a challenge: never a round-1 seat or the challenger.
    function challengeEligible(uint256 id, address w) external view returns (bool ok) {
        if (id >= jobs.length) return false;
        Challenge storage ch = challenges[id];
        if (ch.state != ChallengeState.Open) return false;
        (ok,) = _eligible(id, ch.r, w, 2);
    }

    /// The skill a job was requested under, its body counts, when the reveal
    /// grace after a quorum ends (0 = nothing pending), and its round-1
    /// lottery (0 = not drawn yet).
    function jobInfo(uint256 id) external view returns (bytes32 skill, uint256 bodies_, uint256 drawn, uint64 settleAt, bytes32 rand) {
        Job storage j = _job(id);
        return (j.skill, j.bodies, j.drawn, j.settleAt, j.r.rand);
    }

    /// How sure the verdict is: `agreedBy` distinct runners revealed it (2
    /// or 3 after round 1; plus round 2's after a confirmed challenge), the
    /// challenge state, until when it can be challenged, and `settled`:
    /// no challenge is possible or running any more.
    function assurance(uint256 id) external view returns (uint8 agreedBy, ChallengeState state, uint64 challengeUntil, bool settled) {
        Job storage j = _job(id);
        state = challenges[id].state;
        settled = j.status == Status.Done && state != ChallengeState.Open && (state != ChallengeState.None || block.timestamp >= j.challengeUntil);
        return (j.agreedBy, state, j.challengeUntil, settled);
    }

    function challengeInfo(uint256 id) external view returns (
        address challenger, ChallengeState state, uint256 bond, uint64 start, bytes32 rand,
        uint8 commits, uint8 reveals, address[3] memory seat, bytes32 result, uint64 settleAt
    ) {
        _job(id);
        Challenge storage ch = challenges[id];
        Round storage r = ch.r;
        return (ch.challenger, ch.state, ch.bond, r.start, r.rand, r.commits, r.reveals, r.seat, ch.result, ch.settleAt);
    }

    /// Strikes within the runner's last STRIKE_WINDOW judged seats.
    function strikes(address w) public view returns (uint256 n) {
        for (uint8 r = workers[w].recent; r != 0; r >>= 1) n += r & 1;
    }

    /// Requests per minute right now, times DECAY_MINUTES (the busiest
    /// recent minute, fading linearly to 0 over DECAY_MINUTES).
    function load() public view returns (uint256) {
        uint64 m = uint64(block.timestamp / 60);
        uint256 a = _fade(loadCount, loadMinute, m);
        uint256 b = _fade(peakCount, peakMinute, m);
        return a > b ? a : b;
    }

    /// Bodies for a job requested now: DEFENDERS + ceil(requests per minute
    /// / CAPACITY_PER_BODY), at most NeuroControl.maxBodies().
    function bodies() public view returns (uint256 n) {
        uint256 unit = DECAY_MINUTES * CAPACITY_PER_BODY;
        n = DEFENDERS + (load() + unit - 1) / unit;
        uint256 cap = address(control) != address(0) ? control.maxBodies() : type(uint16).max;
        if (n > cap) n = cap;
    }

    function quarantined(address w) public view returns (bool) {
        uint64 q = workers[w].quarantinedAt;
        if (q == 0) return false;
        return address(control) == address(0) || q >= control.releasedAt(w);
    }

    /// Seated in a defender seat and still fit for it (incl. a recent heartbeat).
    function isDefender(address w) public view returns (bool) {
        if (w == address(0)) return false;
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return _fit(w);
        return false;
    }

    function defenders() external view returns (address[4] memory) {
        return defender;
    }

    // ---- immune system ----

    /// Anyone may call it. Vacates defender seats whose runner is no longer
    /// fit (removed from the roster, quarantined, unbonded, below the bond,
    /// or silent for longer than defenderTimeout), then refills empty seats
    /// from NeuroControl's roster, at most maxRegrowPerHour refills per
    /// clock hour.
    function regrow() external returns (uint256 filled) {
        if (address(control) == address(0)) revert NoControl();
        for (uint256 i = 0; i < DEFENDERS; i++) {
            address d = defender[i];
            if (d != address(0) && !_fit(d)) {
                defender[i] = address(0);
                emit DefenderVacated(d, i);
            }
        }
        uint64 hour = uint64(block.timestamp / 1 hours);
        if (regrowHour != hour) { regrowHour = hour; regrownThisHour = 0; }
        uint256 cap = control.maxRegrowPerHour();
        address[] memory r = control.roster();
        uint256 next = 0;
        for (uint256 i = 0; i < DEFENDERS && regrownThisHour < cap; i++) {
            if (defender[i] != address(0)) continue;
            for (; next < r.length; next++) {
                address cand = r[next];
                if (!_seated(cand) && _fit(cand)) {
                    defender[i] = cand;
                    regrownThisHour += 1;
                    filled += 1;
                    emit DefenderSeated(cand, i);
                    next++;
                    break;
                }
            }
            if (next >= r.length && defender[i] == address(0)) break;
        }
    }

    // ---- internals ----

    function _job(uint256 id) private view returns (Job storage) {
        if (id >= jobs.length) revert BadJob();
        return jobs[id];
    }

    function _paused() private view returns (bool) {
        return address(control) != address(0) && control.paused();
    }

    function _draw(uint256 id, Job storage j, Round storage r, uint8 round) private {
        if (block.number <= r.startBlock) revert TooEarly();
        r.rand = keccak256(abi.encode(j.seed, block.prevrandao, round));
        emit Drawn(id, round, r.rand);
    }

    /// Takes a seat in round `round` (1 or 2) for msg.sender.
    function _take(uint256 id, Job storage j, Round storage r, uint8 round, bytes32 commitment) private {
        Worker storage wk = workers[msg.sender];
        if (!wk.active) revert NotWorker();
        if (_paused()) revert Paused();
        if (block.timestamp >= r.start + commitWindow || r.commits == SEATS) revert NoSeat();
        if (r.rand == 0) _draw(id, j, r, round);
        (bool ok, bool asDefender) = _eligible(id, r, msg.sender, round);
        if (!ok) revert NotChosen();
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == msg.sender) revert AlreadyIn();
        r.seat[r.commits] = msg.sender;
        r.commitOf[r.commits] = commitment;
        r.commits += 1;
        if (asDefender) r.defenders += 1;
        wk.lastSeen = uint64(block.timestamp);
    }

    /// Checks msg.sender's commitment; returns how many revealed seats now
    /// hold this verdict (itself included).
    function _reveal(Round storage r, bytes32 verdict, bytes32 salt) private returns (uint8 same) {
        uint8 s = _seatOf(r, msg.sender);
        if (r.revealed[s]) revert AlreadyIn();
        if (keccak256(abi.encode(verdict, msg.sender, salt)) != r.commitOf[s]) revert BadReveal();
        r.revealed[s] = true;
        r.verdictOf[s] = verdict;
        r.reveals += 1;
        workers[msg.sender].lastSeen = uint64(block.timestamp);
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) same++;
    }

    /// (eligible, as a defender) for round `round` of job `id`. Round 2
    /// excludes the challenger and every round-1 seat.
    function _eligible(uint256 id, Round storage r, address w, uint8 round) private view returns (bool, bool) {
        Job storage j = jobs[id];
        Worker storage wk = workers[w];
        uint256 total = totalActiveBond;
        if (r.rand == 0 || !wk.active || wk.since >= r.start || total == 0 || quarantined(w)) return (false, false);
        if (round == 2) {
            if (w == challenges[id].challenger) return (false, false);
            for (uint8 i = 0; i < j.r.commits; i++) if (j.r.seat[i] == w) return (false, false);
        }
        uint256 elapsed = block.timestamp - r.start;
        // A defender never goes by the lottery: one per round, more only
        // after the first third of the window while no drawn runner has come.
        if (isDefender(w)) return (r.defenders == 0 || (elapsed * 3 >= commitWindow && r.commits == r.defenders), true);
        uint256 stage = (elapsed * 3) / commitWindow; // 0, 1, 2 inside the window
        // Last third: every active runner (a real random draw must not leave seats empty).
        if (stage >= 2) return (true, false);
        uint256 base = j.drawn;
        if (stage > 0 && base < SEATS) base = SEATS;
        uint256 k = base << stage;
        uint256 x = uint256(keccak256(abi.encode(r.rand, w))) % 1e18;
        return (x * total < k * uint256(wk.bond) * 1e18, false);
    }

    function _seatOf(Round storage r, address w) private view returns (uint8) {
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == w) return i;
        revert NoSeat();
    }

    function _challengeWindow() private view returns (uint256 w) {
        if (address(control) != address(0)) w = control.challengeWindow();
        if (w == 0) w = jobTimeout;
    }

    function _toCommunity(uint256 amount) private {
        if (amount == 0) return;
        if (address(control) != address(0)) credit[control.communityFund()] += amount;
        else rewardPool += amount;
    }

    function _finalize(uint256 id, Job storage j, bytes32 verdict) private {
        Round storage r = j.r;
        j.status = Status.Done;
        j.result = verdict;
        j.challengeUntil = uint64(block.timestamp + _challengeWindow());
        uint8 winners = 0;
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) winners++;
        j.agreedBy = winners;
        uint256 burnCut = (j.fee * BURN_BPS) / 10_000;
        uint256 fundCut = (j.fee * COMMUNITY_BPS) / 10_000;
        uint256 toRunners = j.fee - burnCut - fundCut;
        uint256 share = toRunners / winners;
        fundCut += toRunners - share * winners; // rounding dust
        // Pool reward per winner: at most jobReward and at most a quarter of
        // the fee, within the daily cap.
        uint256 reward = jobReward < j.fee / 4 ? jobReward : j.fee / 4;
        uint64 today = uint64(block.timestamp / 1 days);
        if (rewardDay != today) { rewardDay = today; rewardedToday = 0; }
        uint64 hold = j.challengeUntil + jobTimeout;
        for (uint8 i = 0; i < r.commits; i++) {
            address w = r.seat[i];
            // Every round-1 seat may be slashed by a challenge: its bond stays until then.
            if (workers[w].heldUntil < hold) workers[w].heldUntil = hold;
            if (r.revealed[i] && r.verdictOf[i] == verdict) {
                uint256 pay = share;
                if (reward > 0 && rewardPool >= reward && rewardedToday + reward <= dailyRewardCap) {
                    rewardPool -= reward;
                    rewardedToday += reward;
                    pay += reward;
                }
                credit[w] += pay;
                _judge(w, true);
            } else if (r.revealed[i]) {
                _judge(w, false);
            } else {
                // Not revealed yet: a grace to reveal, then settle() judges it.
                j.settleAt = uint64(block.timestamp) + commitWindow;
            }
        }
        _toCommunity(fundCut);
        totalBurned += burnCut;
        emit FeeSplit(id, share * winners, burnCut, fundCut);
        emit Finalized(id, verdict);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    function _fail(uint256 id, Job storage j, bool timedOut) private {
        j.status = Status.Failed;
        uint256 burnCut = (j.fee * FAIL_BURN_BPS) / 10_000;
        credit[j.requester] += j.fee - burnCut;
        if (timedOut) {
            for (uint8 i = 0; i < j.r.commits; i++) if (!j.r.revealed[i]) _miss(id, j.r.seat[i]);
        }
        totalBurned += burnCut;
        emit FeeSplit(id, 0, burnCut, 0);
        emit JobFailed(id);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    /// Round 2 reached a quorum on `verdict`. Only credits move (no calls out).
    function _resolve(uint256 id, Job storage j, Challenge storage ch, bytes32 verdict) private {
        Round storage r1 = j.r;
        Round storage r2 = ch.r;
        ch.result = verdict;
        bytes32 old = j.result;
        bool overturned = verdict != old;
        ch.state = overturned ? ChallengeState.Overturned : ChallengeState.Confirmed;
        uint256 pot;  // shared by the payees below
        uint256 n;    // payees: round-2 winners, plus round-1 seats that revealed `verdict`
        if (overturned) {
            j.result = verdict;
            for (uint8 i = 0; i < r1.commits; i++) {
                if (!r1.revealed[i] || r1.verdictOf[i] != old) continue;
                address w = r1.seat[i];
                workers[w].rejected += 1;
                pot += _penalize(w, CHALLENGE_SLASH_BPS, false);
                _record(w, true);
            }
            uint256 toChallenger = pot / 2;
            credit[ch.challenger] += ch.bond + toChallenger;
            pot -= toChallenger;
        } else {
            pot = ch.bond;
        }
        uint8 n1;
        for (uint8 i = 0; i < r1.commits; i++) if (r1.revealed[i] && r1.verdictOf[i] == verdict) n1++;
        uint8 n2;
        for (uint8 i = 0; i < r2.commits; i++) if (r2.revealed[i] && r2.verdictOf[i] == verdict) n2++;
        // Confirmed: half for round 2, half for round 1's winners. Overturned:
        // one equal share each for round-2 winners and vindicated round-1 seats.
        uint256 s2;
        uint256 s1;
        if (overturned) {
            n = uint256(n1) + n2;
            s1 = s2 = pot / n;
            j.agreedBy = n1 + n2;
        } else {
            s2 = (pot / 2) / n2;
            s1 = (pot - pot / 2) / n1;
            j.agreedBy += n2;
        }
        uint256 paid;
        for (uint8 i = 0; i < r1.commits; i++) {
            if (r1.revealed[i] && r1.verdictOf[i] == verdict) { credit[r1.seat[i]] += s1; paid += s1; }
        }
        for (uint8 i = 0; i < r2.commits; i++) {
            address w = r2.seat[i];
            if (r2.revealed[i] && r2.verdictOf[i] == verdict) { credit[w] += s2; paid += s2; _judge(w, true); }
            else if (r2.revealed[i]) _judge(w, false);
            else ch.settleAt = uint64(block.timestamp) + commitWindow;
        }
        _toCommunity(pot - paid); // rounding dust
        emit ChallengeResolved(id, ch.state, verdict);
    }

    /// Round 2 without a quorum: bond back, verdict stands but disputed.
    function _dispute(uint256 id, Challenge storage ch, bool timedOut) private {
        ch.state = ChallengeState.Disputed;
        credit[ch.challenger] += ch.bond;
        if (timedOut) {
            for (uint8 i = 0; i < ch.r.commits; i++) if (!ch.r.revealed[i]) _miss(id, ch.r.seat[i]);
        }
        emit ChallengeResolved(id, ChallengeState.Disputed, jobs[id].result);
    }

    function _settleRound(uint256 id, Round storage r, uint64 at) private returns (bool) {
        if (at == 0 || block.timestamp < at) return false;
        for (uint8 i = 0; i < r.commits; i++) if (!r.revealed[i]) _miss(id, r.seat[i]);
        return true;
    }

    /// A judged seat: `ok` = its verdict stood. A rejected verdict costs the
    /// penalty and a strike.
    function _judge(address w, bool ok) private {
        Worker storage wk = workers[w];
        if (ok) {
            wk.agreed += 1;
            _record(w, false);
        } else {
            wk.rejected += 1;
            _penalize(w, PENALTY_BPS, true);
            _record(w, true);
        }
    }

    /// Committed, never revealed: penalty and a strike.
    function _miss(uint256 id, address w) private {
        emit Missed(id, w);
        _penalize(w, PENALTY_BPS, true);
        _record(w, true);
    }

    function _record(address w, bool strike) private {
        Worker storage wk = workers[w];
        wk.recent = uint8(((uint256(wk.recent) << 1) | (strike ? 1 : 0)) & ((1 << STRIKE_WINDOW) - 1));
        if (strike && strikes(w) >= QUARANTINE_AFTER && !quarantined(w)) _quarantine(w);
    }

    /// Out at once: not active, its bond leaves totalActiveBond and starts
    /// unbonding (withdrawable after unbondDelay, minus penalties).
    function _quarantine(address w) private {
        Worker storage wk = workers[w];
        wk.recent = 0;
        wk.quarantinedAt = uint64(block.timestamp);
        if (wk.active) {
            wk.active = false;
            activeWorkers -= 1;
            totalActiveBond -= wk.bond;
        }
        if (wk.unbondAt == 0 && wk.bond > 0) {
            wk.unbondAt = uint64(block.timestamp) + unbondDelay;
            emit UnbondRequested(w, wk.unbondAt);
        }
        emit Quarantined(w);
        for (uint256 i = 0; i < DEFENDERS; i++) {
            if (defender[i] == w) {
                defender[i] = address(0);
                emit DefenderVacated(w, i);
            }
        }
    }

    function _fit(address w) private view returns (bool) {
        if (address(control) == address(0) || !control.defenderApproved(w) || !workers[w].active || quarantined(w)) return false;
        return block.timestamp < uint256(workers[w].lastSeen) + control.defenderTimeout();
    }

    function _seated(address w) private view returns (bool) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return true;
        return false;
    }

    function _seatedDefenders() private view returns (uint256 n) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] != address(0) && _fit(defender[i])) n++;
    }

    /// N requests counted at minute `from`, seen at minute `m`: N*(DECAY-age), 0 after DECAY_MINUTES.
    function _fade(uint256 n, uint64 from, uint64 m) private pure returns (uint256) {
        uint256 age = m - from;
        return age >= DECAY_MINUTES ? 0 : n * (DECAY_MINUTES - age);
    }

    function _countRequest() private {
        uint64 m = uint64(block.timestamp / 60);
        if (m != loadMinute) {
            // The finished minute becomes the peak if it outweighs the fading one.
            if (_fade(loadCount, loadMinute, m) >= _fade(peakCount, peakMinute, m)) { peakCount = loadCount; peakMinute = loadMinute; }
            loadMinute = m;
            loadCount = 0;
        }
        loadCount += 1;
    }

    /// Takes `bps` of the bond: into the reward pool (`toPool`), or returned
    /// for the caller to hand out (a challenge's slash).
    function _penalize(address w, uint16 bps, bool toPool) private returns (uint256 cut) {
        Worker storage wk = workers[w];
        cut = (uint256(wk.bond) * bps) / 10_000;
        if (cut == 0) return 0;
        wk.bond -= uint128(cut);
        if (toPool) rewardPool += cut;
        if (wk.active) totalActiveBond -= cut;
        emit Penalized(w, cut);
        // Below the bond: stop taking new jobs until topped up.
        if (wk.active && wk.bond < workerBond) {
            wk.active = false;
            activeWorkers -= 1;
            totalActiveBond -= wk.bond;
        }
    }
}

contracts/NeuroValidation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IValidationRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IIdentityRegistry {
    function ownerOf(uint256 tokenId) external view returns (address);
    function getApproved(uint256 tokenId) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);
    function webEndpoint(uint256 agentId) external view returns (string memory);
}

/// @title NeuroValidation: ERC-8004 Validation Registry answered by Neuro runners
/// @notice The ERC-8004 Validation Registry interface. Validators here are the
///         bonded NeuroJobs runners with a track record (active, at least
///         `minAgreed` accepted verdicts, no more rejected than accepted):
///         stake-secured re-execution, which ERC-8004 calls "crypto-economic"
///         trust. A runner posts Neuro's verdict on an agent (a contract's
///         identity) as a validation response: the verdict hash and a 0-100
///         score.
///
///         - `validationRequest` / `validationResponse` follow the spec: the
///           agent's owner or operator asks a named validator, and only that
///           validator answers (and it must be a runner when it answers).
///         - `postVerdict` lets a runner publish a verdict on any agent without
///           a request, because an unclaimed contract identity has no owner to
///           ask, and an owner must not be able to keep Neuro's verdicts off
///           its identity. It emits the same two spec events.
///         - Each runner has ONE verdict slot per agent, at
///           `verdictRequestHash(agentId, runner)`. A newer verdict replaces the
///           older one. Verdict slots live in their own namespace: their hash
///           starts with VERDICT_TAG, and `validationRequest` refuses any hash
///           that does, so nobody can pre-create a runner's slot under another
///           agent and steal its verdicts.
///         - `getSummary` counts each validator once per agent: its latest
///           answer there (a verdict or a spec response). One runner cannot
///           outweigh the others by answering many times.
///         - A spec `requestHash` is first come, first served (the spec reads
///           by the bare hash, so it cannot be bound to the requester). Make it
///           commit to the request (e.g. keccak of agentId, validator and the
///           request file); if someone takes it first, `validationRequest`
///           reverts `Exists` and nothing of yours is written, so pick a new
///           hash. Validators should check `getValidationStatus(h).agentId`
///           before answering.
contract NeuroValidation {
    struct ValidationStatus {
        address validatorAddress;
        uint256 agentId;
        uint8 response;      // 0..100
        bytes32 responseHash;
        string tag;
        uint256 lastUpdate;
        bool hasResponse;
    }

    address public immutable identityRegistry;
    IValidationRunners public immutable runners;
    uint32 public immutable minAgreed;
    uint256 public constant MAX_TAG = 64;
    /// First 4 bytes of every postVerdict slot hash ("NVD1"); spec requests may not use them.
    bytes4 public constant VERDICT_TAG = 0x4e564431;
    bytes32 private constant TAG_MASK = 0xffffffff00000000000000000000000000000000000000000000000000000000;

    mapping(bytes32 => ValidationStatus) private _validations;
    mapping(uint256 => bytes32[]) private _agentValidations;
    mapping(address => bytes32[]) private _validatorRequests;
    /// agentId => validator => requestHash of its latest answer on that agent
    mapping(uint256 => mapping(address => bytes32)) private _latest;

    event ValidationRequest(address indexed validatorAddress, uint256 indexed agentId, string requestURI, bytes32 indexed requestHash);
    event ValidationResponse(address indexed validatorAddress, uint256 indexed agentId, bytes32 indexed requestHash,
        uint8 response, string responseURI, bytes32 responseHash, string tag);

    error BadValue();
    error NotAuthorized();
    error Exists();
    error Unknown();
    error NotValidator();
    error NotRunner();
    error ReservedHash();

    constructor(address identityRegistry_, IValidationRunners runners_, uint32 minAgreed_) {
        if (identityRegistry_ == address(0) || address(runners_) == address(0) || minAgreed_ == 0) revert BadValue();
        identityRegistry = identityRegistry_;
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function getIdentityRegistry() external view returns (address) {
        return identityRegistry;
    }

    /// Is `who` a bonded runner with a track record right now?
    function isRunner(address who) public view returns (bool) {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(who);
        return active && agreed >= minAgreed && rejected <= agreed;
    }

    // ---------------------------------------------------------- ERC-8004

    function validationRequest(address validatorAddress, uint256 agentId, string calldata requestURI, bytes32 requestHash) external {
        if (validatorAddress == address(0) || requestHash == bytes32(0)) revert BadValue();
        if (isVerdictHash(requestHash)) revert ReservedHash();
        if (_validations[requestHash].validatorAddress != address(0)) revert Exists();
        IIdentityRegistry reg = IIdentityRegistry(identityRegistry);
        address owner = reg.ownerOf(agentId);
        if (msg.sender != owner && !reg.isApprovedForAll(owner, msg.sender) && reg.getApproved(agentId) != msg.sender) revert NotAuthorized();
        _open(validatorAddress, agentId, requestURI, requestHash);
    }

    function validationResponse(bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) external {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        if (msg.sender != s.validatorAddress) revert NotValidator();
        if (!isRunner(msg.sender)) revert NotRunner();
        _answer(s, requestHash, response, responseURI, responseHash, tag);
    }

    // ------------------------------------------------------------- Neuro

    /// A runner publishes Neuro's verdict on `agentId`: `verdictHash` is the
    /// verdict (as in NeuroJobs, stored as the responseHash), `score` 0-100
    /// (100 = no problems found). A runner has one verdict slot per agent: a
    /// new post replaces its previous verdict there.
    function postVerdict(uint256 agentId, bytes32 verdictHash, uint8 score, string calldata responseURI, string calldata tag)
        external returns (bytes32 requestHash)
    {
        if (!isRunner(msg.sender)) revert NotRunner();
        if (verdictHash == bytes32(0)) revert BadValue();
        IIdentityRegistry(identityRegistry).ownerOf(agentId); // reverts for an unknown agent
        requestHash = verdictRequestHash(agentId, msg.sender);
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) {
            string memory uri;
            try IIdentityRegistry(identityRegistry).webEndpoint(agentId) returns (string memory u) { uri = u; } catch {}
            _open(msg.sender, agentId, uri, requestHash);
        } else if (s.agentId != agentId || s.validatorAddress != msg.sender) {
            revert NotAuthorized(); // unreachable while only postVerdict writes tagged slots; kept as a guard
        }
        _answer(s, requestHash, score, responseURI, verdictHash, tag);
    }

    /// The one verdict slot of `runner` on `agentId`. Its first 4 bytes are VERDICT_TAG.
    function verdictRequestHash(uint256 agentId, address runner) public view returns (bytes32) {
        bytes32 h = keccak256(abi.encode("neuro.verdict.v1", address(this), agentId, runner));
        return (h & ~TAG_MASK) | bytes32(VERDICT_TAG);
    }

    /// Is `requestHash` in the postVerdict namespace (closed to validationRequest)?
    function isVerdictHash(bytes32 requestHash) public pure returns (bool) {
        return bytes4(requestHash) == VERDICT_TAG;
    }

    // ------------------------------------------------------------- reads

    function getValidationStatus(bytes32 requestHash) external view returns (
        address validatorAddress, uint256 agentId, uint8 response, bytes32 responseHash, string memory tag, uint256 lastUpdate
    ) {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        return (s.validatorAddress, s.agentId, s.response, s.responseHash, s.tag, s.lastUpdate);
    }

    /// Average response of answered validations, optionally only from
    /// `validatorAddresses` and with `tag`. Each validator counts once per
    /// agent: only its latest answer on that agent is read.
    function getSummary(uint256 agentId, address[] calldata validatorAddresses, string calldata tag)
        external view returns (uint64 count, uint8 averageResponse)
    {
        bytes32[] storage list = _agentValidations[agentId];
        bytes32 tagHash = keccak256(bytes(tag));
        uint256 total;
        for (uint256 i; i < list.length; i++) {
            ValidationStatus storage s = _validations[list[i]];
            if (!s.hasResponse) continue;
            if (_latest[agentId][s.validatorAddress] != list[i]) continue; // superseded by a newer answer
            if (bytes(tag).length > 0 && keccak256(bytes(s.tag)) != tagHash) continue;
            if (validatorAddresses.length > 0) {
                bool found;
                for (uint256 j; j < validatorAddresses.length; j++) if (validatorAddresses[j] == s.validatorAddress) { found = true; break; }
                if (!found) continue;
            }
            total += s.response;
            count++;
        }
        averageResponse = count > 0 ? uint8(total / count) : 0;
    }

    function getAgentValidations(uint256 agentId) external view returns (bytes32[] memory) {
        return _agentValidations[agentId];
    }

    function getValidatorRequests(address validatorAddress) external view returns (bytes32[] memory) {
        return _validatorRequests[validatorAddress];
    }

    // ------------------------------------------------------------ internal

    function _open(address validatorAddress, uint256 agentId, string memory requestURI, bytes32 requestHash) internal {
        ValidationStatus storage s = _validations[requestHash];
        s.validatorAddress = validatorAddress;
        s.agentId = agentId;
        s.lastUpdate = block.timestamp;
        _agentValidations[agentId].push(requestHash);
        _validatorRequests[validatorAddress].push(requestHash);
        emit ValidationRequest(validatorAddress, agentId, requestURI, requestHash);
    }

    function _answer(ValidationStatus storage s, bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) internal {
        if (response > 100 || bytes(tag).length > MAX_TAG) revert BadValue();
        s.response = response;
        s.responseHash = responseHash;
        s.tag = tag;
        s.lastUpdate = block.timestamp;
        s.hasResponse = true;
        _latest[s.agentId][s.validatorAddress] = requestHash;
        emit ValidationResponse(s.validatorAddress, s.agentId, requestHash, response, responseURI, responseHash, tag);
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IFundable {
    function fund() external payable;
}

/// @title RewardVault: releases the ZETAPHY reward pool at 10% a year
/// @notice The 500,000,000 ZETAPHY set aside for runners and validators sit
///         here instead of in a key-holder's account. Every day, anyone can
///         call `release()`, which pays out the share of the remaining pool
///         that has vested: 10% of what is left per year, in daily steps
///         (0.9^(1/365) is kept each day), so the pool lasts for decades.
///
///         There is NO withdraw function. Governance can only choose who
///         receives the releases (e.g. NeuroJobs' reward pool, a validator
///         rewards contract), and a change only takes effect DELAY after it
///         is announced, so everyone can see it coming. Nobody can make the
///         vault pay faster than the schedule.
contract RewardVault {
    uint256 private constant RAY = 1e27;
    /// 0.9^(1/365) in RAY: keep^365 = 0.9 (to 1e-25)
    uint256 public constant DAILY_KEEP = 999711382710977687364396358;
    uint256 public constant DELAY = 7 days;
    uint256 public constant MAX_SHARES = 8;

    struct Share {
        address to;
        uint16 bps;      // out of 10,000
        bool callFund;   // pay through `fund()` (NeuroJobs, ComputeMarket) instead of a plain transfer
    }

    uint64 public immutable start;
    uint64 public releasedDays;
    address public governance;
    Share[] private _shares;
    Share[] private _pending;
    uint64 public pendingAt; // 0 = nothing pending

    event Released(uint256 day, uint256 amount);
    event Paid(address indexed to, uint256 amount, bool ok);
    event SharesProposed(uint64 effectiveAt);
    event SharesApplied();
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadShares();
    error TooEarly();

    constructor(address governance_, Share[] memory shares_) {
        governance = governance_;
        start = uint64(block.timestamp);
        _check(shares_);
        for (uint256 i = 0; i < shares_.length; i++) _shares.push(shares_[i]);
    }

    receive() external payable {}

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- schedule ----

    function daysElapsed() public view returns (uint256) {
        return (block.timestamp - start) / 1 days;
    }

    /// What `release()` would pay right now.
    function releasable() public view returns (uint256) {
        uint256 n = daysElapsed() - releasedDays;
        if (n == 0) return 0;
        uint256 bal = address(this).balance;
        return bal - (bal * _rpow(DAILY_KEEP, n)) / RAY;
    }

    /// Pays out everything vested since the last release. Anyone may call it.
    function release() public returns (uint256 amount) {
        amount = releasable();
        releasedDays = uint64(daysElapsed()); // before any external call
        if (amount == 0) return 0;
        emit Released(releasedDays, amount);
        uint256 left = amount;
        for (uint256 i = 0; i < _shares.length; i++) {
            Share memory s = _shares[i];
            uint256 part = i + 1 == _shares.length ? left : (amount * s.bps) / 10_000;
            left -= part;
            bool ok;
            if (s.callFund) {
                (ok, ) = s.to.call{value: part}(abi.encodeCall(IFundable.fund, ()));
            } else {
                (ok, ) = s.to.call{value: part}("");
            }
            // A recipient that refuses keeps nothing: the amount stays in the
            // vault (and keeps vesting); a broken recipient cannot block others.
            emit Paid(s.to, ok ? part : 0, ok);
        }
    }

    // ---- recipients ----

    function shares() external view returns (Share[] memory) {
        return _shares;
    }

    function pendingShares() external view returns (Share[] memory) {
        return _pending;
    }

    /// Announces new recipients; they apply DELAY later.
    function proposeShares(Share[] calldata next) external onlyGovernance {
        _check(next);
        delete _pending;
        for (uint256 i = 0; i < next.length; i++) _pending.push(next[i]);
        pendingAt = uint64(block.timestamp + DELAY);
        emit SharesProposed(pendingAt);
    }

    function cancelShares() external onlyGovernance {
        delete _pending;
        pendingAt = 0;
    }

    /// After the delay, anyone may switch to the announced recipients.
    /// What vested before the switch is paid to the old ones first.
    function applyShares() external {
        if (pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        // Take the pending list first: a recipient called during release()
        // must not be able to apply it a second time.
        Share[] memory next = _pending;
        delete _pending;
        pendingAt = 0;
        release();
        delete _shares;
        for (uint256 i = 0; i < next.length; i++) _shares.push(next[i]);
        emit SharesApplied();
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- internals ----

    function _check(Share[] memory s) private pure {
        if (s.length == 0 || s.length > MAX_SHARES) revert BadShares();
        uint256 total;
        for (uint256 i = 0; i < s.length; i++) {
            if (s[i].to == address(0) || s[i].bps == 0) revert BadShares();
            total += s[i].bps;
        }
        if (total != 10_000) revert BadShares();
    }

    /// x^n in RAY fixed point (exponentiation by squaring, rounding half up).
    function _rpow(uint256 x, uint256 n) private pure returns (uint256 z) {
        z = n % 2 != 0 ? x : RAY;
        for (n /= 2; n != 0; n /= 2) {
            x = (x * x + RAY / 2) / RAY;
            if (n % 2 != 0) z = (z * x + RAY / 2) / RAY;
        }
    }
}

contracts/SimpleMultisig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SimpleMultisig: k-of-n owners for ZETAPHY admin roles (testnet)
/// @notice Holds governance of BridgeGuard / BridgeAirlock / StableGateway so
///         that no single key can change limits, prices or lanes. Any owner
///         proposes a call; it runs once `threshold` owners confirmed it.
///         Owners and the threshold change only through the multisig itself.
///         On mainnet prefer an audited Safe; this is small on purpose.
contract SimpleMultisig {
    struct Proposal {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint8 confirmations;
    }

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint8 public threshold;
    Proposal[] public proposals;
    mapping(uint256 => mapping(address => bool)) public confirmed;

    event Proposed(uint256 indexed id, address indexed by, address to, uint256 value);
    event Confirmed(uint256 indexed id, address indexed by);
    event Revoked(uint256 indexed id, address indexed by);
    event Executed(uint256 indexed id);

    error NotOwner();
    error BadConfig();
    error Done();
    error Twice();
    error NotEnough();
    error CallFailed(bytes reason);

    constructor(address[] memory owners_, uint8 threshold_) {
        _setOwners(owners_, threshold_);
    }

    receive() external payable {}

    modifier onlyOwner() { if (!isOwner[msg.sender]) revert NotOwner(); _; }

    function propose(address to, uint256 value, bytes calldata data) external onlyOwner returns (uint256 id) {
        id = proposals.length;
        proposals.push(Proposal(to, value, data, false, 0));
        emit Proposed(id, msg.sender, to, value);
        _confirm(id);
    }

    function confirm(uint256 id) external onlyOwner { _confirm(id); }

    function revoke(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (!confirmed[id][msg.sender]) revert NotEnough();
        confirmed[id][msg.sender] = false;
        p.confirmations -= 1;
        emit Revoked(id, msg.sender);
    }

    function execute(uint256 id) external onlyOwner returns (bytes memory) {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (p.confirmations < threshold) revert NotEnough();
        p.executed = true;
        (bool ok, bytes memory ret) = p.to.call{value: p.value}(p.data);
        if (!ok) revert CallFailed(ret);
        emit Executed(id);
        return ret;
    }

    /// Change owners / threshold: only as a proposal executed by the multisig.
    function setOwners(address[] calldata owners_, uint8 threshold_) external {
        if (msg.sender != address(this)) revert NotOwner();
        for (uint256 i = 0; i < owners.length; i++) isOwner[owners[i]] = false;
        _setOwners(owners_, threshold_);
    }

    function ownerCount() external view returns (uint256) { return owners.length; }
    function proposalCount() external view returns (uint256) { return proposals.length; }

    function _confirm(uint256 id) private {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (confirmed[id][msg.sender]) revert Twice();
        confirmed[id][msg.sender] = true;
        p.confirmations += 1;
        emit Confirmed(id, msg.sender);
    }

    function _setOwners(address[] memory owners_, uint8 threshold_) private {
        if (threshold_ < 2 || threshold_ > owners_.length || owners_.length > 20) revert BadConfig();
        delete owners;
        for (uint256 i = 0; i < owners_.length; i++) {
            address o = owners_[i];
            if (o == address(0) || isOwner[o]) revert BadConfig();
            isOwner[o] = true;
            owners.push(o);
        }
        threshold = threshold_;
    }
}

contracts/StableGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20Permit {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

interface INeuroJobs {
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256);
}

/// @title StableGateway: use the Neuro network paying only in a stablecoin
/// @notice A user who holds a stablecoin but no ZETAPHY signs a job request.
///         Anyone (a "relayer") submits it and pays the gas; in the same
///         transaction the gateway takes the user's stablecoin (the cost of
///         the ZETAPHY fee at a fixed testnet price, plus the relayer's tip)
///         and pays the job fee in ZETAPHY from its own reserve.
///         Testnet: the price is set by the operator, not a market.
contract StableGateway {
    INeuroJobs public immutable jobs;
    address public owner;

    /// stablecoin base units charged per 1 ZETAPHY (1e18 wei); 0 = not accepted
    mapping(address => uint256) public pricePerZeta;
    mapping(address => uint256) public nonces;

    bytes32 public constant REQUEST_TYPEHASH = keccak256(
        "JobRequest(address user,address token,bytes32 chain,string target,uint256 fee,uint256 tip,uint256 maxCost,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    struct JobRequest {
        address user;
        address token;
        bytes32 chain;
        string target;
        uint256 fee;      // ZETAPHY (wei) the job pays
        uint256 tip;      // stablecoin units to the relayer
        uint256 maxCost;  // the most stablecoin the user agrees to spend (cost + tip)
        uint256 nonce;
        uint256 deadline;
    }

    struct Permit { uint256 value; uint256 deadline; uint8 v; bytes32 r; bytes32 s; }

    event PriceSet(address indexed token, uint256 pricePerZeta);
    event Paid(uint256 indexed jobId, address indexed user, address indexed token, uint256 cost, uint256 tip, address relayer);
    event OwnerChanged(address owner);

    error NotOwner();
    error Expired();
    error BadNonce();
    error BadSignature();
    error NotAccepted();
    error TooExpensive();
    error ReserveLow();

    constructor(INeuroJobs jobs_) {
        jobs = jobs_;
        owner = msg.sender;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    receive() external payable {} // ZETAPHY reserve top-up

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    function setOwner(address o) external onlyOwner {
        owner = o;
        emit OwnerChanged(o);
    }

    function setPrice(address token, uint256 price) external onlyOwner {
        pricePerZeta[token] = price;
        emit PriceSet(token, price);
    }

    /// Stablecoin proceeds go to the treasury the operator names.
    function sweep(address token, address to, uint256 amount) external onlyOwner {
        require(IERC20Permit(token).transfer(to, amount), "transfer failed");
    }

    function withdrawReserve(address payable to, uint256 amount) external onlyOwner {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "transfer failed");
    }

    /// Stablecoin cost of a job fee, rounded up.
    function quote(address token, uint256 fee) public view returns (uint256) {
        uint256 p = pricePerZeta[token];
        if (p == 0) revert NotAccepted();
        return (fee * p + 1e18 - 1) / 1e18;
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function hashRequest(JobRequest calldata q) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), keccak256(abi.encode(
            REQUEST_TYPEHASH, q.user, q.token, q.chain, keccak256(bytes(q.target)), q.fee, q.tip, q.maxCost, q.nonce, q.deadline))));
    }

    /// The user already approved this gateway for the stablecoin.
    function request(JobRequest calldata q, bytes calldata sig) external returns (uint256) {
        return _request(q, sig);
    }

    /// Same, with an EIP-2612 permit so the user needs no approve transaction (no gas at all).
    function requestWithPermit(JobRequest calldata q, bytes calldata sig, Permit calldata p) external returns (uint256) {
        // A failed permit is fine if an allowance already exists (e.g. someone front-ran the permit).
        try IERC20Permit(q.token).permit(q.user, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _request(q, sig);
    }

    function _request(JobRequest calldata q, bytes calldata sig) private returns (uint256 jobId) {
        if (block.timestamp > q.deadline) revert Expired();
        if (q.nonce != nonces[q.user]) revert BadNonce();
        if (_recover(hashRequest(q), sig) != q.user) revert BadSignature();
        nonces[q.user] = q.nonce + 1;

        uint256 cost = quote(q.token, q.fee);
        if (cost + q.tip > q.maxCost) revert TooExpensive();
        if (address(this).balance < q.fee) revert ReserveLow();

        require(IERC20Permit(q.token).transferFrom(q.user, address(this), cost), "payment failed");
        if (q.tip > 0) require(IERC20Permit(q.token).transferFrom(q.user, msg.sender, q.tip), "tip failed");
        jobId = jobs.requestFor{value: q.fee}(q.user, q.chain, q.target);
        emit Paid(jobId, q.user, q.token, cost, q.tip, msg.sender);
    }

    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(digest, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("ZETAPHY StableGateway")), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/TestStable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestStable: testnet-only stand-in for USDC / USDT on ZETAPHY testnet
/// @notice Worthless by design. Anyone can take 1,000 from the faucet once a
///         day. Real USDC arrives only through the bridge in stage 3.
///         ERC-20 + EIP-2612 permit, 6 decimals like USDC/USDT.
contract TestStable {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;
    uint256 public constant FAUCET_AMOUNT = 1_000 * 10 ** 6;
    uint256 public constant FAUCET_EVERY = 1 days;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public lastFaucet;

    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    function faucet() external {
        _drip(msg.sender);
    }

    /// Lets a relay pay the gas for someone who has no ZETAPHY yet.
    function faucetTo(address to) external {
        _drip(to);
    }

    function _drip(address to) private {
        require(to != address(0), "to zero");
        require(block.timestamp >= lastFaucet[to] + FAUCET_EVERY, "faucet: once a day");
        lastFaucet[to] = block.timestamp;
        totalSupply += FAUCET_AMOUNT;
        balanceOf[to] += FAUCET_AMOUNT;
        emit Transfer(address(0), to, FAUCET_AMOUNT);
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            require(a >= value, "allowance");
            allowance[from][msg.sender] = a - value;
        }
        _move(from, to, value);
        return true;
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "permit: expired");
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(),
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))));
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "permit: bad s");
        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "permit: bad signature");
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function _move(address from, address to, uint256 value) private {
        require(to != address(0), "to zero");
        uint256 b = balanceOf[from];
        require(b >= value, "balance");
        unchecked { balanceOf[from] = b - value; }
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/ThreatRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The parts of NeuroIdentity (ERC-8004 identity registry) this registry reads:
/// who has claimed the identity of a target ("eip155:<id>:0x<lowercase hex>").
interface IIdentityOwners {
    function agentOfTarget(bytes32 caip10Hash) external view returns (uint256);
    function ownerOf(uint256 agentId) external view returns (address);
}

/// @title ThreatRegistry: Neuro's immune system (stage 4)
/// @notice A flag here states a reproducible fact about code, not guilt: what
///         the code can do, or did in a reproducible test (Reason), with the
///         evidence that shows it (a Neuro reportHash or the hash of another
///         reproducible report, plus a short URI). Active, bonded NeuroJobs
///         runners with a track record vote to flag a key. At QUORUM distinct
///         votes the key is flagged, and every Neuro instance that reads this
///         registry warns about it, on every chain. A flag is cleared the same
///         way (QUORUM votes to clear).
///
///         Keys:
///           - a code fingerprint (Neuro's fp1: sha256 of the code with
///             addresses/immutables masked), so every copy of the code is found
///           - codeKey(h):         EVM code with extcodehash h on ZETAPHY
///           - addressKey(id, a):  address a on the chain with EVM id `id`
///         voteBatch lets a runner vote on a fingerprint together with the code
///         hashes and addresses it found for it, in one tx (one evidence for the
///         batch); each key still needs its own quorum. BridgeAirlock / BridgeGuard
///         refuse flagged sources and recipients, and the ZETAPHY wallet refuses to
///         sign calls to flagged code.
///
///         Evidence: every flag vote carries one (reportHash != 0, uri at most
///         MAX_URI bytes); every vote's evidence is in its Voted event, and the
///         evidence of the round's first flag vote (the one whose reason the flag
///         shows) is stored: evidenceOf(key).
///
///         Right of reply: the party behind a key may post a response (at most
///         MAX_RESPONSE bytes) that wallets show next to the flag: responseOf(key).
///         Who may answer for a key (respond / appeal, `_mayAnswer`):
///           - addressKey(block.chainid, a) or codeKey(a.codehash) for a contract a
///             on ZETAPHY: a itself or its current owner();
///           - addressKey(id, a) on any EVM chain (and on ZETAPHY): the owner of
///             the claimed ERC-8004 identity of "eip155:<id>:<a>" in NeuroIdentity
///             (optional: `identity`, zero = off);
///           - any key: the responder governance assigned to it (`responder`), e.g.
///             for fp1 keys, which no contract can be tied to on chain. Once
///             assigned, only it may answer for that key.
///         A response never changes the flag.
///
///         Appeal: whoever may answer for a flagged key may appeal(key), paying
///         `appealBond` (appeals are off until governance sets a community fund).
///         That opens an appeal round, voted with voteAppeal, by runners who
///         neither voted for the flag nor backed it (voted/backed of the round that
///         set it, `flagRound`): fresh eyes. The appellant cannot vote in it.
///           - QUORUM appeal votes to clear: the flag is cleared, the bond is
///             refunded, and each runner who set the flag gets a strike
///             (`strikes`, a public record only: see below).
///           - QUORUM appeal votes to keep: the flag stands; the bond goes to the
///             community fund (not to the voters, so reviewers gain nothing by
///             keeping a flag).
///           - Neither within `appealWindow`: anyone may expireAppeal; the bond is
///             refunded (nobody reviewed it: not the appellant's fault).
///           - The flag cleared otherwise meanwhile (the normal clear vote,
///             governance protecting the key): the bond is refunded.
///         Funds are never pushed inside these calls: refunds are credited
///         (`owed`, taken with withdraw) and the fund's share with payFund, so
///         a failing receiver cannot block a vote. Strikes slash nothing: the
///         runners' bonds are in NeuroJobs, and an automatic penalty would let a
///         colluding appeal quorum silence honest runners; governance and the
///         runners' tools can read them.
///
///         Checks on the runners (a small quorum must not freeze bridges or wallets):
///           - Warning vs enforcement. isFlagged / is*Flagged answer at once
///             (Neuro warns, the wallet shows a warning). is*Enforced answer true
///             only once a flag is `enforceDelay` old; everything that BLOCKS
///             (BridgeGuard, BridgeAirlock, NeuroLane watchers, the wallet's
///             refusal) reads those, so governance has that long to look.
///             Things that only HOLD (reversible: BridgeAirlock's release, a
///             BridgeGuard call the adapter retries) hold at once on is*Flagged.
///           - Fast lane. A flag is enforced at once (no enforceDelay) when
///             `fastQuorum` distinct runners stand behind it (a supermajority,
///             governance's knob, default 2 x quorum; runners can still add
///             their vote to a flag that is already standing), or when
///             governance or a guardian calls enforceNow(key). Clearing (same
///             quorum) or protecting the key lifts it as before.
///           - Protected keys. Governance (the chain's gov module through
///             MsgEVMCall, or a multisig) can protect keys, e.g. the bridge's
///             own contracts and code hashes or a common token's code. A
///             protected key cannot be flagged; protecting a flagged key clears it.
contract ThreatRegistry {
    IRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed; // verdicts a runner must have had accepted to vote

    /// What the code does, or did in a reproducible test. Never a claim about intent.
    enum Reason {
        None,
        CannotSellInSimulation,   // a simulated buy worked, the sell failed or returned almost nothing
        UnlimitedMint,            // an address can mint new tokens without a cap
        OwnerCanBlockTransfers,   // an owner/admin can stop holders from transferring or selling
        OwnerCanMoveHolderFunds,  // an owner/admin can move or burn tokens or funds held by others
        SameNameAsKnownToken,     // same name/symbol as a known token, at a different address
        SweepsApprovedTokens,     // in a test, moved tokens approved to it to an address the holder did not choose
        Other                     // another code fact: see the evidence
    }

    struct Entry {
        bool flagged;
        Reason reason;
        uint64 updatedAt;
        uint32 round;        // bumps on every flag/clear so old votes stop counting
        uint8 votes;
        bool fast;           // enforced at once (fastQuorum or enforceNow)
        uint8 support;       // distinct runners behind the standing flag
        uint64 fastAt;       // when it went fast
    }

    struct Evidence {
        bytes32 reportHash;  // Neuro reportHash, or the hash of another reproducible report
        address by;          // the runner who gave it
        uint64 at;
        string uri;          // where the report can be read (at most MAX_URI bytes)
    }

    struct Response {
        address by;
        uint64 at;
        uint256 chainId;     // the subject answered for (0: a governance-assigned responder)
        address account;
        string text;         // at most MAX_RESPONSE bytes
    }

    struct Appeal {
        address appellant;   // zero: no appeal open
        uint64 openedAt;
        uint32 flagRound;    // the round that set the flag: its voters and backers may not vote
        uint8 clearVotes;
        uint8 keepVotes;
        uint128 bond;
    }

    bytes16 private constant HEX = "0123456789abcdef";
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_RESPONSE = 500;
    uint256 public constant MAX_APPEAL_BOND = 1000 ether;
    uint64 public constant MIN_APPEAL_WINDOW = 1 days;
    uint64 public constant MAX_APPEAL_WINDOW = 90 days;

    mapping(bytes32 => Entry) public entries;
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public voted;
    /// Runners who backed a standing flag after it was set (fast lane); kept apart
    /// from `voted`, which stays exactly the quorum that set it (ThreatReports pays those).
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public backed;
    bytes32[] public flaggedList;
    mapping(bytes32 => Evidence) private _evidence;
    /// Flag voters per round (at most quorum each): the runners an upheld appeal strikes.
    mapping(bytes32 => mapping(uint32 => address[])) private _flaggers;

    /// The chain's gov module (MsgEVMCall) or a multisig.
    address public governance;
    /// Seconds a flag waits before the is*Enforced views (which block) report it.
    uint64 public enforceDelay;
    uint64 public constant MAX_ENFORCE_DELAY = 30 days;
    /// Keys governance vouched for: never flagged.
    mapping(bytes32 => bool) public protectedKey;
    /// Distinct flag votes that enforce a standing flag at once (0: off).
    uint8 public fastQuorum;
    /// Guardians (set by governance) may enforceNow; they cannot flag, clear or protect.
    mapping(address => bool) public guardian;

    // ---- right of reply and appeal ----
    IIdentityOwners public identity;               // zero: the identity route is off
    mapping(bytes32 => address) public responder;  // governance-assigned; exclusive once set
    mapping(bytes32 => Response) private _responses;
    uint128 public appealBond;
    uint64 public appealWindow = 14 days;
    address public communityFund;                  // zero: appeals off
    mapping(bytes32 => Appeal) public appeals;
    mapping(bytes32 => uint32) public appealCount; // appeal ids per key, from 1
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public appealVoted;
    mapping(address => uint32) public strikes;
    mapping(address => uint256) public owed;       // refunds, taken with withdraw()
    uint256 public fundOwed;                       // the community fund's share, sent with payFund()

    event Voted(bytes32 indexed fingerprint, address indexed runner, bool flag, Reason reason, bytes32 reportHash, string uri);
    event Flagged(bytes32 indexed fingerprint, Reason reason);
    event Cleared(bytes32 indexed fingerprint);
    event Protected(bytes32 indexed key, bool on);
    event EnforceDelaySet(uint64 delay);
    event GovernanceSet(address governance);
    event Supported(bytes32 indexed key, address indexed runner, uint8 support, bytes32 reportHash);
    event FastEnforced(bytes32 indexed key, address indexed by);
    event FastQuorumSet(uint8 fastQuorum);
    event GuardianSet(address indexed who, bool on);
    event Responded(bytes32 indexed key, address indexed by, uint256 chainId, address account, string text);
    event ResponderSet(bytes32 indexed key, address responder);
    event IdentitySet(address identity);
    event AppealsSet(uint128 bond, uint64 window, address fund);
    event Appealed(bytes32 indexed key, uint32 indexed id, address indexed appellant, uint128 bond);
    event AppealVoted(bytes32 indexed key, uint32 indexed id, address indexed runner, bool clear, bytes32 reportHash, string uri);
    event AppealClosed(bytes32 indexed key, uint32 indexed id, uint8 outcome); // 1 cleared, 2 kept, 3 expired, 4 flag cleared otherwise
    event Struck(address indexed runner, bytes32 indexed key, uint32 strikes);
    event Paid(address indexed to, uint256 amount);

    error NotRunner();
    error AlreadyVoted();
    error NoChange();
    error NotGovernance();
    error ProtectedKey(bytes32 key);
    error NotGuardian();
    error NotFlagged();
    error NoEvidence();
    error TooLong();
    error NotResponder();
    error AppealsOff();
    error BadBond(uint256 bond);
    error AppealOpen();
    error NoAppeal();
    error AppealExpired();
    error NotYet();
    error NotFresh();
    error PayFailed();

    constructor(IRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, uint64 enforceDelay_) {
        require(quorum_ >= 2, "quorum");
        require(governance_ != address(0), "governance");
        require(enforceDelay_ <= MAX_ENFORCE_DELAY, "delay");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        enforceDelay = enforceDelay_;
        fastQuorum = quorum_ > 127 ? 255 : quorum_ * 2;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    /// Applies to flags already standing too (they are measured from when they were set).
    function setEnforceDelay(uint64 d) external onlyGov {
        require(d <= MAX_ENFORCE_DELAY, "delay");
        enforceDelay = d;
        emit EnforceDelaySet(d);
    }

    /// Fast lane: this many distinct runners behind a flag enforce it at once.
    /// Above quorum (a supermajority), or 0 to turn the fast lane off.
    function setFastQuorum(uint8 f) external onlyGov {
        require(f == 0 || f > quorum, "fastQuorum");
        fastQuorum = f;
        emit FastQuorumSet(f);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// NeuroIdentity, for the identity route of the right of reply (zero: off).
    function setIdentity(IIdentityOwners i) external onlyGov {
        identity = i;
        emit IdentitySet(address(i));
    }

    /// The only party that may answer for `key` (zero: the on-chain routes again).
    function setResponder(bytes32 key, address who) external onlyGov {
        responder[key] = who;
        emit ResponderSet(key, who);
    }

    /// Appeal bond, window and the community fund that keeps bonds of appeals
    /// that confirmed the flag. A zero fund turns appeals off (open ones still
    /// close normally); a new bond applies to new appeals only.
    function setAppeals(uint128 bond, uint64 window, address fund) external onlyGov {
        require(bond <= MAX_APPEAL_BOND, "bond");
        require(window >= MIN_APPEAL_WINDOW && window <= MAX_APPEAL_WINDOW, "window");
        appealBond = bond;
        appealWindow = window;
        communityFund = fund;
        emit AppealsSet(bond, window, fund);
    }

    /// Governance or a guardian enforces a standing flag at once (money moving
    /// now). Only a flag the runners' quorum already set; protected keys can
    /// never be flagged, so never enforced either.
    function enforceNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast) revert NoChange();
        _fast(e, key);
    }

    function _fast(Entry storage e, bytes32 key) private {
        e.fast = true;
        e.fastAt = uint64(block.timestamp);
        emit FastEnforced(key, msg.sender);
    }

    /// Protect (or unprotect) keys. Protecting clears a flag at once and drops
    /// any votes in progress; unprotecting does not flag anything back.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            protectedKey[k] = on;
            emit Protected(k, on);
            if (!on) continue;
            Entry storage e = entries[k];
            if (e.flagged || e.votes != 0) {
                bool was = e.flagged;
                _reset(e, k);
                e.round += 1;
                e.updatedAt = uint64(block.timestamp);
                if (was) emit Cleared(k);
            }
        }
    }

    /// keccak256 of empty code: every account without code has it, so it is never a threat.
    bytes32 public constant EMPTY_CODEHASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /// The key under which EVM code with this extcodehash is flagged.
    function codeKey(bytes32 codeHash) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.code", codeHash));
    }

    /// The key under which an address on a given chain (EVM chain id) is flagged.
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.address", chainId, who));
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function _checkEvidence(bool required, bytes32 reportHash, string calldata uri) private pure {
        if (required && reportHash == bytes32(0)) revert NoEvidence();
        if (bytes(uri).length > MAX_URI) revert TooLong();
    }

    /// Vote to flag (flag = true, with a reason and its evidence) or to clear
    /// (flag = false; evidence optional). `fingerprint` is any key: a fp1
    /// fingerprint, codeKey(..) or addressKey(..).
    function vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && protectedKey[fingerprint]) revert ProtectedKey(fingerprint);
        if (!_vote(fingerprint, flag, reason, reportHash, uri)) revert NoChange();
    }

    /// One runner's votes on several keys at once, e.g. a fingerprint plus the
    /// code hashes and addresses of its copies, with one evidence for the batch.
    /// Keys already in that state, or already voted on by this runner this
    /// round, are skipped (not an error), so the same list can be sent again as
    /// copies are found. Protected keys are skipped when flagging. On a key
    /// already flagged, a flag vote adds this runner's support (toward
    /// fastQuorum) once.
    function voteBatch(bytes32[] calldata keys, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external returns (uint256 counted) {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && reason == Reason.None) revert NoChange();
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            Entry storage e = entries[k];
            if (flag && protectedKey[k]) continue;
            if (flag && e.flagged) { if (_support(e, k, reportHash)) counted++; continue; }
            if (e.flagged == flag || voted[k][e.round][msg.sender]) continue;
            _vote(k, flag, reason, reportHash, uri);
            counted++;
        }
        if (counted == 0) revert NoChange();
    }

    /// A flag vote on a standing flag: one more runner behind it (once per
    /// runner, counting the quorum that set it). False when nothing changed.
    function _support(Entry storage e, bytes32 key, bytes32 reportHash) private returns (bool) {
        if (e.fast || e.support == type(uint8).max) return false;
        uint32 r = e.round - 1; // the round that set the flag
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender]) return false;
        backed[key][r][msg.sender] = true;
        e.support += 1;
        emit Supported(key, msg.sender, e.support, reportHash);
        if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, key);
        return true;
    }

    /// The flag (or the votes in progress) is gone: an open appeal ends with its bond refunded.
    function _reset(Entry storage e, bytes32 key) private {
        e.flagged = false;
        e.reason = Reason.None;
        e.votes = 0;
        e.fast = false;
        e.support = 0;
        e.fastAt = 0;
        delete _evidence[key];
        if (appeals[key].appellant != address(0)) _closeAppeal(key, 4);
    }

    function _vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) private returns (bool) {
        Entry storage e = entries[fingerprint];
        if (flag && reason == Reason.None) return false;
        if (flag && e.flagged) {
            if (voted[fingerprint][e.round - 1][msg.sender] || backed[fingerprint][e.round - 1][msg.sender]) revert AlreadyVoted();
            return _support(e, fingerprint, reportHash);
        }
        if (e.flagged == flag) return false;
        if (voted[fingerprint][e.round][msg.sender]) revert AlreadyVoted();
        voted[fingerprint][e.round][msg.sender] = true;
        e.votes += 1;
        if (flag) {
            _flaggers[fingerprint][e.round].push(msg.sender);
            if (e.reason == Reason.None) { // the round's first flag vote: its reason and evidence are what the flag shows
                e.reason = reason;
                _evidence[fingerprint] = Evidence(reportHash, msg.sender, uint64(block.timestamp), uri);
            }
        }
        emit Voted(fingerprint, msg.sender, flag, reason, reportHash, uri);
        if (e.votes >= quorum) {
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            if (flag) {
                e.flagged = true;
                e.support = e.votes;
                e.votes = 0;
                flaggedList.push(fingerprint);
                emit Flagged(fingerprint, e.reason);
                if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, fingerprint);
            } else {
                _reset(e, fingerprint);
                emit Cleared(fingerprint);
            }
        }
        return true;
    }

    // ---- right of reply ----

    /// "eip155:<chainId>:0x<lowercase hex>", NeuroIdentity's spelling of an EVM target.
    function _caip10(uint256 chainId, address a) private pure returns (bytes memory out) {
        bytes memory digits = new bytes(78);
        uint256 n = 78;
        uint256 v = chainId;
        do { digits[--n] = bytes1(uint8(48 + v % 10)); v /= 10; } while (v != 0);
        bytes memory id = new bytes(78 - n);
        for (uint256 i = 0; i < id.length; i++) id[i] = digits[n + i];
        bytes memory hexa = new bytes(40);
        uint160 x = uint160(a);
        for (uint256 i = 40; i > 0; i--) { hexa[i - 1] = HEX[x & 15]; x >>= 4; }
        out = abi.encodePacked("eip155:", id, ":0x", hexa);
    }

    /// The claimed owner of the identity of `account` on chain `chainId` (zero: none, unclaimed or off).
    function _identityOwner(uint256 chainId, address account) private view returns (address) {
        IIdentityOwners idr = identity;
        if (address(idr) == address(0)) return address(0);
        try idr.agentOfTarget(keccak256(_caip10(chainId, account))) returns (uint256 agentId) {
            if (agentId == 0) return address(0);
            try idr.ownerOf(agentId) returns (address o) { return o == address(idr) ? address(0) : o; } catch { return address(0); }
        } catch { return address(0); }
    }

    /// The `owner()` of a contract on this chain (zero: none).
    function _ownerOf(address a) private view returns (address) {
        if (a.code.length == 0) return address(0);
        (bool ok, bytes memory r) = a.staticcall{gas: 50_000}(abi.encodeWithSignature("owner()"));
        if (!ok || r.length < 32) return address(0);
        uint256 w = abi.decode(r, (uint256));
        return w >> 160 == 0 ? address(uint160(w)) : address(0);
    }

    /// May msg.sender answer for `key` as the party behind (chainId, account)? (See the notice.)
    function mayAnswer(bytes32 key, uint256 chainId, address account, address who) public view returns (bool) {
        address r = responder[key];
        if (r != address(0) || chainId == 0) return r != address(0) && who == r;
        if (who == address(0)) return false;
        bool local = chainId == block.chainid;
        if (key != addressKey(chainId, account)) {
            // On this chain, the code key of a contract answers too (every copy's owner is a party to it).
            if (!local || account.code.length == 0 || key != codeKey(account.codehash)) return false;
        }
        if (local && (who == account || who == _ownerOf(account))) return true;
        return who == _identityOwner(chainId, account);
    }

    /// Post (or replace; empty text removes) the response to the flag on `key`,
    /// as the party behind (chainId, account): see the notice. Never changes the flag.
    function respond(bytes32 key, uint256 chainId, address account, string calldata text) external {
        if (bytes(text).length > MAX_RESPONSE) revert TooLong();
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        if (bytes(text).length == 0) delete _responses[key];
        else _responses[key] = Response(msg.sender, uint64(block.timestamp), chainId, account, text);
        emit Responded(key, msg.sender, chainId, account, text);
    }

    function responseOf(bytes32 key) external view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        Response storage r = _responses[key];
        return (r.text, r.by, r.at, r.chainId, r.account);
    }

    /// The evidence of the flag on `key` (of the round's first flag vote; while
    /// a flag round is still open, that vote's). Zero when there is none.
    function evidenceOf(bytes32 key) external view returns (bytes32 reportHash, string memory uri, address by, uint64 at) {
        Evidence storage v = _evidence[key];
        return (v.reportHash, v.uri, v.by, v.at);
    }

    // ---- appeal ----

    /// Appeal the standing flag on `key` as the party behind (chainId, account),
    /// paying exactly appealBond. Opens an appeal round (voteAppeal).
    function appeal(bytes32 key, uint256 chainId, address account) external payable returns (uint32 id) {
        if (communityFund == address(0)) revert AppealsOff();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (appeals[key].appellant != address(0)) revert AppealOpen();
        if (msg.value != appealBond) revert BadBond(appealBond);
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        id = ++appealCount[key];
        appeals[key] = Appeal(msg.sender, uint64(block.timestamp), e.round - 1, 0, 0, uint128(msg.value));
        emit Appealed(key, id, msg.sender, uint128(msg.value));
    }

    /// A fresh runner's vote in the open appeal on `key`: clear the flag (clear =
    /// true) or keep it, with its own evidence (the reproduction it ran).
    /// Runners who voted for or backed the flag, and the appellant, cannot vote.
    function voteAppeal(bytes32 key, bool clear, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(true, reportHash, uri);
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp >= uint256(a.openedAt) + appealWindow) revert AppealExpired();
        uint32 r = a.flagRound;
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender] || msg.sender == a.appellant) revert NotFresh();
        uint32 id = appealCount[key];
        if (appealVoted[key][id][msg.sender]) revert AlreadyVoted();
        appealVoted[key][id][msg.sender] = true;
        emit AppealVoted(key, id, msg.sender, clear, reportHash, uri);
        if (clear) {
            if (++a.clearVotes < quorum) return;
            address[] storage fl = _flaggers[key][r];
            for (uint256 i = 0; i < fl.length; i++) emit Struck(fl[i], key, ++strikes[fl[i]]);
            _closeAppeal(key, 1);
            Entry storage e = entries[key];
            _reset(e, key);
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            emit Cleared(key);
        } else if (++a.keepVotes >= quorum) {
            _closeAppeal(key, 2);
        }
    }

    /// Nobody decided within appealWindow: the bond is refunded, the flag stands.
    function expireAppeal(bytes32 key) external {
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp < uint256(a.openedAt) + appealWindow) revert NotYet();
        _closeAppeal(key, 3);
    }

    /// outcome 2 (kept): the bond to the community fund; otherwise refunded.
    function _closeAppeal(bytes32 key, uint8 outcome) private {
        Appeal memory a = appeals[key];
        delete appeals[key];
        if (outcome == 2) fundOwed += a.bond;
        else owed[a.appellant] += a.bond;
        emit AppealClosed(key, appealCount[key], outcome);
    }

    /// Take refunded bonds.
    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        _pay(msg.sender, amount);
    }

    /// Send kept bonds to the community fund (anyone may call it).
    function payFund() external {
        uint256 amount = fundOwed;
        fundOwed = 0;
        _pay(communityFund, amount);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
        emit Paid(to, amount);
    }

    // ---- warning views: true as soon as the quorum flagged (Neuro warns on these) ----

    function isFlagged(bytes32 fingerprint) public view returns (bool, Reason) {
        Entry storage e = entries[fingerprint];
        return (e.flagged, e.reason);
    }

    /// EVM code with this code hash (extcodehash) is flagged. Empty code never is.
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isFlagged(codeKey(codeHash));
    }

    function isAddressFlagged(uint256 chainId, address who) public view returns (bool, Reason) {
        return isFlagged(addressKey(chainId, who));
    }

    /// For contracts on this chain: `who` itself is flagged, or the code at it is.
    function isContractFlagged(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressFlagged(block.chainid, who);
        if (f) return (f, r);
        return isCodeFlagged(who.codehash);
    }

    // ---- enforcement views: true only once the flag is enforceDelay old, or at once
    //      through the fast lane (these block) ----

    /// When a standing flag starts to be enforced (0: not flagged).
    function enforcedFrom(bytes32 key) public view returns (uint64) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        uint64 normal = e.updatedAt + enforceDelay;
        return e.fast && e.fastAt < normal ? e.fastAt : normal;
    }

    function isEnforced(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged || (!e.fast && block.timestamp < uint256(e.updatedAt) + enforceDelay)) return (false, Reason.None);
        return (true, e.reason);
    }

    function isCodeEnforced(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isEnforced(codeKey(codeHash));
    }

    function isAddressEnforced(uint256 chainId, address who) public view returns (bool, Reason) {
        return isEnforced(addressKey(chainId, who));
    }

    function isContractEnforced(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressEnforced(block.chainid, who);
        if (f) return (f, r);
        return isCodeEnforced(who.codehash);
    }

    function flaggedCount() external view returns (uint256) {
        return flaggedList.length;
    }
}

contracts/ThreatReports.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of ThreatRegistry this contract reads.
interface IThreatRegistryView {
    function governance() external view returns (address);
    function quorum() external view returns (uint8);
    function voted(bytes32 key, uint32 round, address runner) external view returns (bool);
    function entries(bytes32 key) external view returns (
        bool flagged, uint8 reason, uint64 updatedAt, uint32 round, uint8 votes, bool fast, uint8 support, uint64 fastAt);
}

/// @title ThreatReports: anyone can point the Neuro runners at a contract to check
/// @notice A user who wants a contract's code checked pays a small fee and
///         reports it: report(key, chainKey, target, note). Runners' tools
///         watch the Reported event, run Neuro on the target and, if a
///         reproducible code fact shows up (ThreatRegistry.Reason, with its
///         evidence), flag the key in the ThreatRegistry (the usual quorum;
///         reports never flag anything by themselves, and a report is a request
///         to check, not a finding).
///         The fee is the anti-spam and the runners' reward:
///           - the key is flagged after the report: the runners who set that
///             flag (the registry's quorum of that round) share the fee; each
///             claims its share (claim);
///           - not flagged within `ttl`: the fee goes to the community fund.
///         settle(id) decides which (anyone may call it).
///         Input is bounded: a note of at most MAX_NOTE bytes, one key per report.
///         Governance is the ThreatRegistry's governance.
contract ThreatReports {
    struct Report {
        bytes32 key;          // ThreatRegistry key: fp1, codeKey(..) or addressKey(..)
        bytes32 chainKey;     // where the target lives, e.g. "eip155:56" or "bsc" (bytes32 string)
        address target;       // the contract on that chain (zero: none given)
        address reporter;
        uint64 createdAt;
        uint8 state;          // 0 open, 1 flagged (runners claim), 2 not flagged (to the fund)
        uint32 flagRound;     // the registry round whose voters share the fee
        uint128 fee;          // what was paid
        uint128 share;        // each voter's share once flagged
        uint8 claims;         // shares paid (at most the registry's quorum)
    }

    uint256 public constant MAX_NOTE = 280;
    uint256 public constant MAX_FEE = 100 ether;
    uint64 public constant MIN_TTL = 1 days;
    uint64 public constant MAX_TTL = 365 days;

    IThreatRegistryView public immutable registry;
    uint256 public fee;
    uint64 public ttl;
    address public communityFund;
    Report[] public reports;
    mapping(uint256 => mapping(address => bool)) public claimed;

    event Reported(uint256 indexed id, bytes32 indexed key, bytes32 indexed chainKey, address target, address reporter, uint256 fee, string note);
    event Settled(uint256 indexed id, bool flagged, uint256 share);
    event Claimed(uint256 indexed id, address indexed runner, uint256 amount);
    event FeeSet(uint256 fee);
    event TtlSet(uint64 ttl);
    event CommunityFundSet(address fund);

    error NotGovernance();
    error BadFee(uint256 fee);
    error NoteTooLong();
    error BadKey();
    error AlreadyFlagged();
    error NotSettled();
    error AlreadySettled();
    error NotYet();
    error NotVoter();
    error PayFailed();

    constructor(IThreatRegistryView registry_, address communityFund_, uint256 fee_, uint64 ttl_) {
        require(communityFund_ != address(0), "fund");
        require(fee_ <= MAX_FEE, "fee");
        require(ttl_ >= MIN_TTL && ttl_ <= MAX_TTL, "ttl");
        registry = registry_;
        communityFund = communityFund_;
        fee = fee_;
        ttl = ttl_;
    }

    modifier onlyGov() { if (msg.sender != registry.governance()) revert NotGovernance(); _; }

    function setFee(uint256 f) external onlyGov { require(f <= MAX_FEE, "fee"); fee = f; emit FeeSet(f); }
    function setTtl(uint64 t) external onlyGov { require(t >= MIN_TTL && t <= MAX_TTL, "ttl"); ttl = t; emit TtlSet(t); }
    function setCommunityFund(address f) external onlyGov { require(f != address(0), "fund"); communityFund = f; emit CommunityFundSet(f); }

    /// Ask the runners to check a contract. `key` is the registry key the runners
    /// would flag; send exactly `fee`. A key that is already flagged needs no
    /// report (and would pay nobody for new work), so it is refused.
    function report(bytes32 key, bytes32 chainKey, address target, string calldata note) external payable returns (uint256 id) {
        if (msg.value != fee) revert BadFee(fee);
        if (bytes(note).length > MAX_NOTE) revert NoteTooLong();
        if (key == bytes32(0)) revert BadKey();
        (bool flagged, , , , , , , ) = registry.entries(key);
        if (flagged) revert AlreadyFlagged();
        id = reports.length;
        reports.push(Report(key, chainKey, target, msg.sender, uint64(block.timestamp), 0, 0, uint128(msg.value), 0, 0));
        emit Reported(id, key, chainKey, target, msg.sender, msg.value, note);
    }

    /// Flagged since the report: the voters of that flag share the fee. Not
    /// flagged and older than ttl: the fee goes to the community fund.
    function settle(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 0) revert AlreadySettled();
        (bool flagged, , uint64 updatedAt, uint32 round, , , , ) = registry.entries(r.key);
        if (flagged && updatedAt >= r.createdAt) {
            uint256 q = registry.quorum();
            r.state = 1;
            r.flagRound = round - 1; // the round that set the standing flag
            r.share = uint128(r.fee / q);
            uint256 dust = r.fee - r.share * q;
            if (dust != 0) _pay(communityFund, dust);
            emit Settled(id, true, r.share);
        } else if (block.timestamp >= uint256(r.createdAt) + ttl) {
            r.state = 2;
            _pay(communityFund, r.fee);
            emit Settled(id, false, 0);
        } else revert NotYet();
    }

    /// A runner who voted for the flag that settled this report takes its share.
    function claim(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 1) revert NotSettled();
        if (claimed[id][msg.sender]) revert AlreadySettled();
        if (!registry.voted(r.key, r.flagRound, msg.sender)) revert NotVoter();
        if (r.claims >= registry.quorum()) revert AlreadySettled(); // never more than the fee
        r.claims += 1;
        claimed[id][msg.sender] = true;
        _pay(msg.sender, r.share);
        emit Claimed(id, msg.sender, r.share);
    }

    function reportCount() external view returns (uint256) {
        return reports.length;
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }
}

contracts/VaultTestRecipients.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only recipients for RewardVault.

/// Refuses every payment.
contract RefusingRecipient {
    receive() external payable { revert("no"); }
}

interface IVault {
    function applyShares() external;
    function release() external returns (uint256);
}

/// Tries to re-enter the vault while being paid.
contract ReentrantRecipient {
    IVault public vault;
    uint256 public attempts;
    function setVault(address v) external { vault = IVault(v); }
    receive() external payable {
        attempts += 1;
        try vault.applyShares() {} catch {}
        try vault.release() {} catch {}
    }
}
